  'Adet döngüsü bir adetin ilk gününden bir sonrakinin ilk gününe kadar geçen süredir.': 'El ciclo menstrual va desde el primer día de una regla hasta el primer día de la siguiente.',
  'Adet döngüsü geçmişim': 'Mi historial menstrual',
  'Adet gecikmesi, hafif kramp veya az miktarda lekelenme olabilir. Ev gebelik testi pozitif çıkabilir.': 'Puede haber retraso de la regla, calambres leves o un ligero manchado. Un test de embarazo puede dar positivo.',
  'Adet kanaması genellikle 2–7 gün sürer.': 'El sangrado menstrual suele durar 2–7 días.',
  'Adet sancısı (dismenore)': 'Dolor menstrual (dismenorrea)',
