  'Aile hekimi izlemi ve aşılar. D vitamini düzenli verilmeli; demir desteği 4. ayda başlar (doz hekim tarafından belirlenir).': 'Seguimiento con el médico de familia y vacunas. La vitamina D debe darse con regularidad; el hierro empieza a los 4 meses (la dosis la fija el médico).',
