  'Aile sofrasına az tuzlu, yaşa uygun kıvamda katıl. Günde 3 öğün + 2 ara öğün. Günlük süt yaklaşık 2 su bardağını aşmamalı. Emzirme isteğe bağlı olarak sürebilir. Seçici yeme bu yaşta olağandır.': 'Se une a las comidas familiares con poca sal y textura adecuada. 3 comidas + 2 tentempiés al día. La leche no debería pasar de unos 2 vasos diarios. La lactancia puede seguir si se desea. Comer con selectividad es normal a esta edad.',
