  'Ateşi ve verilen ilacı saatleriyle not et.': 'Anote la temperatura y los medicamentos dados con la hora.',
  'Ateşin derecesinden bağımsız olarak hemen 112’yi ara: nöbet geçirme, morarma, nefes almada zorluk, bardakla bastırınca solmayan döküntü, uyandırılamama ya da aşırı uyku hâli, ense sertliği, bıngıldakta şişlik, 8 saatten uzun süre ıslak bez olmaması.': 'Sea cual sea la temperatura, llama de inmediato al número de emergencias local si hay: convulsiones, color azulado, dificultad para respirar, un sarpullido que no desaparece al presionar con un vaso, imposibilidad de despertar o somnolencia extrema, rigidez de cuello, fontanela abombada o más de 8 horas sin pañal mojado.',
