  'Bebek uyanıkken ve gözetim altındayken kısa yüzüstü oyun fırsatları sağlayın; zorlanma varsa uzmanla görüşün.': 'Dé ratos cortos boca abajo mientras su bebé esté despierto y vigilado; si le cuesta, hable con un especialista.',
