  'Bir sese dokun; tekrar dokununca durur. Bir gürültü ile bir ninniyi aynı anda çalabilirsin. Sesler telefonda üretilir, internet gerekmez.': 'Toca un sonido; vuelve a tocarlo para detenerlo. Puedes reproducir un ruido y una nana a la vez. Los sonidos se generan en el teléfono; no necesitas internet.',
  'Bir tutam maydanoz': 'Un puñado de perejil',
  'Bir uzmandan veya destek gruplarından yardım iste.': 'Pida ayuda a un profesional o a grupos de apoyo.',
  'Bir yıl düzenli korunmasız ilişkiye rağmen gebelik olmaması infertilite olarak değerlendirilir.': 'No conseguir el embarazo tras un año de relaciones regulares sin protección se considera infertilidad.',
  'Bir şarkıyı tekrar ederek birlikte söyleyin.': 'Canten juntos una canción repitiéndola.',
  'Biraz planlamayla bebekle seyahat keyifli olabilir.': 'Con algo de planificación, viajar con un bebé puede ser agradable.',
  'Bireysel alerjileri kontrol edin.': 'Tenga en cuenta las alergias individuales.',
  'Biri 112\'yi arasın.': 'Pida a alguien que llame al número de emergencias local.',
  'Birim testleri': 'Pruebas unitarias',
  'Birincil adet sancısı genellikle adetin ilk 1–2 gününde görülür.': 'El dolor menstrual primario suele notarse los primeros 1–2 días de la regla.',
  'Birkaç adım yürür; nesneleri üst üste koymayı dener. Tanıdık kişileri isimle tanır.': 'Da unos pasos; intenta apilar objetos. Reconoce a las personas conocidas por su nombre.',
  'Birkaç brokoli çiçeği': 'Unos ramilletes de brócoli',
