  'Birlikte izle ve izlediklerinizi konuş.': 'Vean juntos y hablen de lo que han visto.',
  'Birçok anne sütünün yetmediğinden endişelenir; çoğu zaman süt yeterlidir ve bebek iyi büyür.': 'Muchas madres temen no tener suficiente leche; normalmente sí la tienen y el bebé crece bien.',
  'Birçok gebede enerji artmaya başlar.': 'Muchas embarazadas empiezan a sentirse con más energía.',
  'Bisiklet çevirme hareketi ve karın masajı rahatlatabilir.': 'Los movimientos de bicicleta con las piernas y el masaje en la barriga pueden ayudar.',
