  'Blenderdan geçirip kıvamını sıcak suyla ayarlayın.': 'Tritúrela y ajuste la textura con agua caliente.',
  'Blenderdan geçirip sıcak servis edin.': 'Tritúrela y sirva caliente.',
  'Blenderdan geçirmeden önce çorbayı birkaç dakika ılıtın; sıcak buhar kapağı itebilir.': 'Deje templar la sopa unos minutos antes de triturarla; el vapor caliente puede levantar la tapa.',
  'Blok dizme, taklit, resimli kitap, basit ritim ve serbest hareket oyunları sunun.': 'Ofrezca bloques para apilar, imitación, libros de imágenes, ritmos sencillos y juego libre de movimiento.',
  'Blokları üst üste koyup birlikte yıkın.': 'Apilen los bloques y tírenlos juntos.',
  'Body': 'Body',
  'Bol su iç; idrarını tutma.': 'Beba mucha agua; no aguante las ganas de orinar.',
  'Bol sıvı al, dengeli beslen; demir desteğini hekimine sor.': 'Beba suficiente y coma equilibrado; pregunte a su médico por los suplementos de hierro.',
  'Bol sıvı ve dinlenme sağla; ateşi takip et.': 'Dé muchos líquidos y reposo; vigile la fiebre.',
