  'Boy, kilo ve baş çevresi': 'Talla, peso y perímetro cefálico',
  'Boy, kilo ve baş çevresi kayıtlarının tarih sırasıyla takibi.': 'Seguimiento por fecha de talla, peso y perímetro cefálico.',
