  'Boyun ayarı': 'Ajuste del cuello',
  'Boyun kaslarındaki gerginlik (tortikolis) bebeğin hep aynı tarafa bakmasına neden olabilir.': 'Los músculos del cuello tensos (tortícolis) pueden hacer que el bebé mire siempre al mismo lado.',
  'Boyun çevresinde güvenli uyuma dikkat edin.': 'Compruebe que se ajusta con seguridad al cuello.',
  'Boyunu ekle (vücut kitle indeksi için)': 'Añade tu estatura (para el índice de masa corporal)',
  'Boyut': 'Tamaño',
  'Boyut uyumu': 'Tamaño adecuado',
  'Boğulma (yabancı cisim) ilk yardımı': 'Primeros auxilios en atragantamiento (cuerpo extraño)',
  'Boğulma sessiz ve çok hızlı gerçekleşir; küçük çocuklar birkaç santimetre suda bile boğulabilir.': 'El ahogamiento es silencioso y muy rápido; los niños pequeños pueden ahogarse en pocos centímetros de agua.',
  'Boğulma tehlikesi sonrası öksürük, nefes darlığı veya halsizlik.': 'Tos, falta de aire o debilidad tras un casi ahogamiento.',
  'Boş AI yanıtı alındı.': 'Se recibió una respuesta de IA vacía.',
  'Boş profil silinsin mi?': '¿Eliminar el perfil vacío?',
  'Boş öğün: {0}': 'Comida vacía: {0}',
  'Brahms Ninnisi': 'Canción de cuna de Brahms',
  'Brokoli ve patates ezmesi': 'Puré de brócoli y patata',
  'Brokoliyi buharda yumuşatıp ince kıyın.': 'Cueza el brócoli al vapor hasta que esté tierno y píquelo fino.',
  'Brokoliyi çiçeklerine ayırıp yıkayın; patatesi ve soğanı doğrayın.': 'Separe el brócoli en ramilletes y lávelo; pique la patata y la cebolla.',
  'Bronz gibi yiğit': 'Héroe como el bronce',
  'Bronz; sağlam': 'Bronce; robusto',
  'Bronşiolit (çoğunlukla RSV) 2 yaş altında hırıltı ve hızlı solunuma yol açabilir.': 'La bronquiolitis (casi siempre por VRS) puede causar pitidos y respiración rápida en menores de 2 años.',
  'Bu aralıkta kayıt bulunmuyor.': 'No hay registros en este intervalo.',
  'Bu ay ({0} gün): {1} ml mama, {2} dk emzirme, {3} ek gıda\nÖnceki ayın ilk {4} günü: {5} ml mama, {6} dk emzirme, {7} ek gıda\nMama farkı: {8}{9} ml': 'Este mes ({0} días): {1} ml de fórmula, {2} min de lactancia, {3} comidas sólidas\nPrimeros {4} días del mes pasado: {5} ml de fórmula, {6} min de lactancia, {7} comidas sólidas\nDiferencia de fórmula: {8}{9} ml',
  'Bu ay ({0} gün): {1} sa {2} dk\nÖnceki ayın ilk {3} günü: {4} sa {5} dk\nGünlük kayıt ortalaması: {6} saat': 'Este mes ({0} días): {1} h {2} min\nPrimeros {3} días del mes pasado: {4} h {5} min\nPromedio diario de registros: {6} horas',
  'Bu ay ne yedirebilirim?': '¿Qué le puedo dar de comer este mes?',
  'Bu ay neler önemli?': '¿Qué es importante este mes?',
  'Bu başlıkla ilgili kişisel durumunuzu değerlendirmek için ilgili uzmana danışın.': 'Consulta al especialista correspondiente para valorar tu situación personal sobre este tema.',
  'Bu belirtiler gebeliğin her döneminde ciddiye alınmalıdır.': 'Estos síntomas deben tomarse en serio en cualquier etapa del embarazo.',
  'Bu bilgiler yalnızca bu telefonda, şifreli olarak saklanır. Acil durumda yakınların ya da sağlık personeli için hızlıca gösterebilirsin.': 'Esta información se guarda solo en este teléfono, cifrada. En una emergencia puedes mostrarla rápidamente a tus seres queridos o al personal sanitario.',
  'Bu bilgiler yalnızca uygulamaya girilen kayıtların özetidir. Eksik kayıtlar gerçek günlük toplamları yansıtmayabilir. Sağlık tavsiyesi veya tanı değildir.': 'Esto es solo un resumen de los registros introducidos en la app. Los registros que faltan pueden no reflejar los totales diarios reales. No es un consejo de salud ni un diagnóstico.',
  'Bu bölüm hakkında': 'Acerca de esta sección',
  'Bu bölüm yalnızca sizin girdiğiniz aşı, kontrol ve gelişim notlarını takip eder. Resmî aşı takvimini otomatik oluşturmaz; tıbbi değerlendirme yerine geçmez. Aşı tarihlerini sağlık kuruluşunuzla doğrulayın.': 'Esta sección solo hace seguimiento de las notas de vacunas, controles y desarrollo que introduces. No crea automáticamente el calendario oficial de vacunación ni sustituye una valoración médica. Confirma las fechas de las vacunas con tu profesional de salud.',
  'Bu cihazda kayıtlı oturum': 'Sesión guardada en este dispositivo',
  'Bu cihazdaki kayıt sayıları; gerçek yönetici paneli değildir': 'Número de registros en este dispositivo; no es un panel de administración real',
  'Bu cihazdaki kayıtlarımı sil': 'Eliminar mis registros de este dispositivo',
  'Bu doğum tarihinden önceye ait kayıtlar var. Tarihi kontrol edin veya önce o kayıtları düzenleyin.': 'Hay registros con fecha anterior a esta fecha de nacimiento. Revisa la fecha o edita primero esos registros.',
  'Bu dönemde bebek oturur, emekler, tutunarak kalkar ve ilk anlamlı seslerini çıkarır.': 'En esta etapa el bebé se sienta, gatea, se pone de pie y emite sus primeros sonidos con significado.',
  'Bu dönemde beslenmenin temeli anne sütü veya uygun bebek mamasıdır. Ek gıda, su ve beslenme değişiklikleri için sağlık uzmanınızın önerilerini izleyin.': 'En esta etapa la base de la alimentación es la leche materna o una fórmula infantil adecuada. Siga las indicaciones de su profesional sobre sólidos, agua y cambios de alimentación.',
  'Bu ekran uygulama içi kontrol listesidir; telefon bildirimi göndermez.': 'Esta pantalla es una lista de comprobación dentro de la app; no envía notificaciones al teléfono.',
  'Bu ekran yalnızca bu cihazda tutulan bazı kayıtların sayısını gösterir. Gerçek yönetici yetkilendirmesi, merkezi kullanıcılar, moderasyon, gelir ve analitik verileri henüz mevcut değildir.': 'Esta pantalla solo muestra el número de algunos registros guardados en este dispositivo. Aún no hay autorización de administrador real, usuarios centrales, moderación, ingresos ni análisis.',
  'Bu ekran yalnızca seçilen çocuğun yeni günlük kayıtlarını özetler. Eski ana bebek kayıtları otomatik aktarılmaz. Sağlık istatistikleri tanı amacı taşımaz.': 'Esta pantalla solo resume los registros nuevos del diario del niño seleccionado. Los registros principales antiguos del bebé no se transfieren automáticamente. Las estadísticas de salud no sirven para diagnosticar.',
  'Bu ekran yalnızca sunucu tarafından doğrulanmış yöneticilere veri gösterir. Kullanıcıların sağlık kayıtları burada görüntülenmez.': 'Esta pantalla solo muestra datos a administradores verificados por el servidor. Aquí no se muestran los registros de salud de los usuarios.',
  'Bu ekrandan ödeme alınmaz. Mağaza ürünleri, satın alma/geri yükleme, sunucu tarafında makbuz doğrulama ve abonelik haklarının denetlenmesi tamamlanmadan satış açılmayacak.': 'En esta pantalla no se cobra nada. Las ventas no se abrirán hasta completar los productos de la tienda, la compra/restauración, la verificación de recibos en el servidor y las comprobaciones de derechos de suscripción.',
  'Bu filtrelerde içerik bulunamadı.': 'No se encontró contenido para estos filtros.',
  'Bu filtrelerde tarif bulunamadı.': 'No se encontraron recetas para estos filtros.',
  'Bu filtrelere uygun tarif bulunamadı.': 'Ninguna receta coincide con estos filtros.',
  'Bu filtreye uygun içerik bulunamadı.': 'Ningún contenido coincide con este filtro.',
  'Bu filtreye uygun modül bulunamadı.': 'Ningún módulo coincide con este filtro.',
  'Bu grafikler persentil veya tıbbi değerlendirme değildir.': 'Estos gráficos no son percentiles ni una valoración médica.',
  'Bu gün kayıt yok': 'No hay registros este día',
  'Bu gün ve öğünde başka bir tarif var. Değiştirilsin mi?': 'Ya hay otra receta para este día y comida. ¿Reemplazarla?',
  'Bu güne ait kayıt yok. Satırlardaki + butonuyla ekleyebilirsin.': 'No hay registros este día. Puedes añadirlos con el botón + de cada fila.',
  'Bu günlük belirtileri ve kontrolleri not etmek içindir; tanı, tedavi veya doğurganlık tahmini sunmaz. Şiddetli veya ani belirtilerde sağlık kuruluşuna başvurun.': 'Este diario sirve para anotar síntomas y controles; no ofrece diagnóstico, tratamiento ni predicciones de fertilidad. Ante síntomas graves o repentinos, acude a un centro de salud.',
  'Bu hafta / önceki hafta • mama': 'Esta semana / semana pasada • fórmula',
  'Bu hafta / önceki hafta • uyku': 'Esta semana / semana pasada • sueño',
  'Bu hafta iyi giden bir şeyi ve geliştirmek istediğiniz bir alanı yazın. Gelecek hafta için tek bir uygulanabilir adım seçin.': 'Escriba algo que salió bien esta semana y un aspecto que quiera mejorar. Elija un solo paso posible para la semana que viene.',
  'Bu hafta için eksik malzeme bulunamadı.': 'No faltan ingredientes esta semana.',
  'Bu hafta yapılacaklar': 'Pendientes de esta semana',
  'Bu hesaplama yaklaşık bilgi sunar; doktorun belirlediği gebelik haftası ve doğum tarihi esas alınmalıdır.': 'Este cálculo es aproximado; la semana de embarazo y la fecha de parto que fije tu médico tienen prioridad.',
  'Bu hesaplamalar tahminidir; tıbbi değerlendirme yerine geçmez.': 'Estos cálculos son estimaciones; no sustituyen una valoración médica.',
  'Bu içerik finansal danışmanlık değildir.': 'Este contenido no es asesoramiento financiero.',
  'Bu içerik genel bilgilendirme amaçlıdır. Tıbbi değerlendirme yerine geçmez.': 'Este contenido es de información general. No sustituye una valoración médica.',
  'Bu içerikler genel bilgilendirme amaçlıdır; kişisel tıbbi değerlendirme yerine geçmez.': 'Este contenido es de información general; no sustituye una valoración médica personal.',
  'Bu içerikler genel bilgilendirme amaçlıdır; tanı ve tedavi yerine geçmez. Acil durumda 112\'yi ara.': 'Este contenido es de información general; no sustituye el diagnóstico ni el tratamiento. En una emergencia, llama al número de emergencias local.',
  'Bu işlem geri alınamaz.': 'Esta acción no se puede deshacer.',
  'Bu işlem sunucu üzerinde uygulanır. Devam edilsin mi?': 'Esta acción se aplica en el servidor. ¿Continuar?',
  'Bu kartı sağlık personeline gösterebilirsin.': 'Puedes mostrar esta tarjeta al personal sanitario.',
  'Bu karşılaştırma ürün türlerine ait seçim ölçütlerini gösterir. Marka, teknik model, fiyat veya gerçek ürün performansı karşılaştırması değildir.': 'Esta comparación muestra criterios de elección por tipo de producto. No es una comparación de marcas, modelos técnicos, precios ni rendimiento real.',
  'Bu katalog marka, satıcı, güncel fiyat, stok veya satın alma bağlantısı içermez.': 'Este catálogo no contiene marcas, vendedores, precios actuales, stock ni enlaces de compra.',
  'Bu kategoride ara': 'Buscar en esta categoría',
  'Bu kategoride henüz kayıt yok.': 'Aún no hay registros en esta categoría.',
  'Bu kategoride kayıtlı ürün bulunmuyor.': 'No hay productos guardados en esta categoría.',
  'Bu kayıt takvimi otomatik bildirim veya resmi randevu onayı sağlamaz.': 'Este registro no ofrece avisos automáticos ni confirmación oficial de citas.',
  'Bu kayıtlar cihazın güvenli depolama alanında tutulur; otomatik bulut yedeği değildir. Tıbbi değerlendirme ya da tedavi önerisi yerine geçmez.': 'Estos registros se guardan en el almacenamiento seguro del dispositivo; no son una copia automática en la nube. No sustituyen una valoración médica ni un consejo de tratamiento.',
  'Bu kayıtlar kişisel takip içindir; tanı ve tedavi yerine geçmez.': 'Estos registros son para seguimiento personal; no sustituyen el diagnóstico ni el tratamiento.',
  'Bu kontrol yalnızca çocuk profillerini ve çocuk bazlı günlük kayıtlarını inceler. Verileri silmez, değiştirmez veya otomatik taşımaz. Eski ana bebek kayıtları kapsam dışındadır.': 'Esta comprobación solo revisa los perfiles de niños y los registros de diario de cada niño. No elimina, cambia ni mueve datos automáticamente. Los registros principales antiguos del bebé quedan fuera de alcance.',
  'Bu konuda uygulamada bilgi bulamadım. Soruyu farklı kelimelerle (ör. "uyku", "ek gıda", "aşı") deneyebilir veya sağlık profesyoneline danışabilirsin.': 'No encontré información sobre esto en la app. Prueba otras palabras (p. ej., «sueño», «alimentación complementaria», «vacuna») o pregunta a un profesional de salud.',
  'Bu liste cihazınızdaki manuel kontrolleri takip eder. Tamamlanması uygulamanın mağazada yayınlanmaya hazır olduğunu garanti etmez. ': 'Esta lista sigue las comprobaciones manuales en tu dispositivo. Completarla no garantiza que la app esté lista para publicarse en la tienda. ',
  'Bu liste doğum tarihinden hesaplanan bilgilendirme planıdır; aşı yapıldığını göstermez. 1 Eylül 2026 suçiçeği ikinci doz güncellemesi dikkate alınmıştır. Erken doğum, eksik doz ve özel risk durumlarında kişisel plan gerekir.': 'Esta lista es un plan informativo calculado a partir de la fecha de nacimiento; no indica que las vacunas se hayan puesto. Se tiene en cuenta la actualización del 1 de septiembre de 2026 sobre la segunda dosis de varicela. El parto prematuro, las dosis perdidas y los riesgos especiales requieren un plan personal.',
  'Bu liste kaynak kodun mevcut kapsamını gösterir; canlı sunucu kontrolü değildir. Hiçbir madde otomatik olarak tamamlandı sayılmaz.': 'Esta lista muestra el alcance actual del código fuente; no es una comprobación de servidor en vivo. Ningún elemento se cuenta como completado automáticamente.',
  'Bu oran yalnızca manuel işaretlenen maddeleri gösterir; kodun çalıştığını veya mağaza onayını doğrulamaz.': 'Este porcentaje solo muestra los elementos marcados manualmente; no verifica que el código funcione ni que la tienda lo haya aprobado.',
  'Bu oturum kaydedilmeden silinsin mi?': '¿Eliminar esta sesión sin guardar?',
  'Bu rehber genel bilgi sunar; çocuğunuzun bireysel gelişimi ve sağlık ihtiyaçları için hekiminize danışın. Aylar arasında bazı öneriler benzer olabilir.': 'Esta guía ofrece información general; consulta a tu médico sobre el desarrollo y las necesidades de salud de tu hijo. Algunos consejos pueden parecerse entre meses.',
  'Bu rehber genel bilgi ve kişisel not tutma amaçlıdır. Doğum sonrası bakımda sağlık ekibinizin önerileri önceliklidir.': 'Esta guía es para información general y notas personales. En el cuidado posparto, los consejos de tu equipo de salud tienen prioridad.',
  'Bu rehber genel bilgilendirme amaçlıdır; tıbbi tanı ve tedavi yerine geçmez.': 'Esta guía es de información general; no sustituye el diagnóstico ni el tratamiento médico.',
  'Bu rehber tıbbi tanı, kişisel risk değerlendirmesi veya doktor takibinin yerine geçmez.': 'Esta guía no sustituye el diagnóstico médico, la evaluación personal de riesgos ni el seguimiento médico.',
  'Bu saatlerde başka bir uyku kaydı var. Çakışan kayıt eklenemez.': 'Hay otro registro de sueño en estas horas. No se pueden añadir registros que se solapan.',
  'Bu sayfa tanı koymaz ve ilaç dozu önermez. Eşikler genel bilgilendirme amaçlıdır; doktorunun söyledikleri önceliklidir.': 'Esta página no diagnostica ni recomienda dosis de medicamentos. Los umbrales son información general; lo que diga tu médico tiene prioridad.',
  'Bu sepet yalnızca taslak kaydıdır. Sipariş veya ödeme işlemi yapmaz.': 'Esta cesta es solo un borrador. No hace pedidos ni cobra.',
  'Bu sonuç tıbbi doğruluk veya tam yedekleme garantisi değildir.': 'Este resultado no garantiza exactitud médica ni una copia completa.',
  'Bu süreler kayıt bazlıdır; uyku ihtiyacı için tıbbi değerlendirme yerine geçmez.': 'Estas duraciones se basan en los registros; no sustituyen una valoración médica de las necesidades de sueño.',
  'Bu sürüm çevrimdışı bir forum taslağıdır. Konular yalnızca bu cihazda görünür. Diğer kullanıcılarla paylaşım henüz aktif değildir.': 'Esta versión es un borrador de foro sin conexión. Los temas solo se ven en este dispositivo. Compartir con otros usuarios aún no está activo.',
  'Bu sırada tavada zeytinyağıyla sarımsak ve pul biberi 30 saniye kavurun.': 'Mientras, sofría el ajo y la guindilla en aceite de oliva 30 segundos.',
