  'Daha fazla tarif göster ({0} kaldı)': 'Mostrar más recetas (quedan {0})',
  'Daha hafif bir seçenek için köfteleri 200 °C fırında, yağlı kâğıt üzerinde 18–20 dakika pişirebilirsiniz.': 'Para una opción más ligera, hornéelas sobre papel a 200 °C 18–20 minutos.',
  'Daha mutlu': 'Más feliz',
  'Daha sık ama daha az miktarda besle.': 'Dé de comer más a menudo y en menor cantidad.',
  'Daha sık emzir; ten tene temas kur.': 'Dé el pecho más a menudo; haga piel con piel.',
  'Daha önce dışa aktarılan yedekler ve panoya kopyalanan içerikler ayrıca silinmelidir. Kayıtları silmek açık rızanı geri almak anlamına gelir; uygulama bir sonraki açılışta yeniden onay ister.': 'Las copias que exportaste antes y el contenido copiado al portapapeles deben eliminarse por separado. Eliminar los registros significa retirar tu consentimiento explícito; la app volverá a pedirlo la próxima vez que se abra.',
  'Dalya çiçeği': 'Dalia',
  'Damla dozları ve süresi hekim tarafından belirlenir.': 'La dosis en gotas y la duración las decide el médico.',
  'Damlaları her gün aynı saatte vermek unutmayı azaltır; uygulamada hatırlatıcı kurabilirsin.': 'Dar las gotas cada día a la misma hora evita olvidos; puede poner un recordatorio en la app.',
  'Damlayı yanlışlıkla fazla verdiysen Ulusal Zehir Danışma Merkezi: 114.': 'Si por error dio demasiadas gotas, llame al centro de toxicología.',
