  'Demir': 'Hierro',
  'Demir damlası dişlerde geçici leke yapabilir; sonra ağzı su ile temizle.': 'Las gotas de hierro pueden manchar los dientes temporalmente; enjuague la boca con agua después.',
  'Demir deposu 4–6. aydan sonra azalır; demir eksikliği gelişimi etkileyebilir.': 'Las reservas de hierro bajan tras 4–6 meses; la carencia puede afectar el desarrollo.',
  'Demir desteği gerekip gerekmediğini doktoruna sor.': 'Pregunte a su médico si necesita suplementos de hierro.',
  'Demir eksikliği belirtileri: halsizlik, solukluk, çarpıntı.': 'Signos de falta de hierro: cansancio, palidez, palpitaciones.',
  'Demir eksikliği ve kansızlık': 'Déficit de hierro y anemia',
  'Demir gibi güçlü han': 'Kan fuerte como el hierro',
  'Demir kan yapımı ve beyin gelişimi için gereklidir; bebekler, çocuklar ve kadınlar eksikliğe yatkındır.': 'El hierro es necesario para formar sangre y para el desarrollo cerebral; bebés, niños y mujeres tienen tendencia a la carencia.',
  'Demir takviyesi doktor önerisiyle ve uygun dozda kullanılmalıdır.': 'Los suplementos de hierro deben tomarse por indicación médica y a la dosis adecuada.',
  'Demir ve kalsiyum ihtiyacı artar; beslenmeni ve desteklerini hekiminle planla.': 'Aumentan las necesidades de hierro y calcio; planifique la dieta y los suplementos con su médico.',
  'Demir, çinko, iyot, kalsiyum ve omega-3 açısından dikkatli planlama gerekir.': 'El hierro, el zinc, el yodo, el calcio y el omega-3 requieren una planificación cuidadosa.',
  'Demir; sağlam': 'Hierro; robusto',
  'Demirden zengin besinler (et, yumurta sarısı, mercimek) erken dönemde önemlidir.': 'Los alimentos ricos en hierro (carne, yema de huevo, lentejas) son importantes al principio.',
  'Demirden zengin beslenme': 'Alimentación rica en hierro',
  'Demirden zengin öğünlerle C vitamini içeren besinler emilimi artırır; çay ve kahveyi öğünlerden uzak iç.': 'Los alimentos con vitamina C junto con comidas ricas en hierro mejoran la absorción; tome té y café lejos de las comidas.',
