  'Diş temizliğine ilk dişle başlayın; yaşa uygun florürlü macun miktarını diş hekimiyle doğrulayın.': 'Limpie los dientes desde el primero; consulte con el dentista la cantidad de pasta con flúor adecuada a su edad.',
  'Diş ve ağız bakımını sağlık uzmanıyla planlayın. Büyüme ölçümlerini tarihleriyle kaydedin; gelişim temposunu başka çocuklarla karşılaştırmayın.': 'Planifique el cuidado de dientes y boca con un profesional. Anote las medidas de crecimiento con fecha; no compare el ritmo de desarrollo con otros niños.',
