  'Doğranmış patates, patlıcan, kabak ve domatesi ekleyin.': 'Añada la patata, la berenjena, el calabacín y el tomate picados.',
  'Doğranmış patlıcan ve suyu ekleyip 10 dakika kaynatın.': 'Añada la berenjena picada y el agua y hierva 10 minutos.',
  'Doğranmış sebzeleri tavuk suyuna ekleyin.': 'Añada las verduras picadas al caldo de pollo.',
  'Doğranmış sebzeleri yağda 5 dakika soteleyin.': 'Saltee las verduras picadas 5 minutos en aceite.',
  'Doğranmış soğan ve havucu yağda soteleyin.': 'Saltee la cebolla y la zanahoria picadas en aceite.',
  'Doğranmış soğanı yağda yumuşatıp salçayı kavurun.': 'Sofría la cebolla picada en el aceite y rehogue el concentrado.',
  'Doğru kavramada bebeğin ağzı geniş açık, dudakları dışa dönük ve meme başının çevresindeki koyu alanın büyük kısmı ağzındadır.': 'Con un buen agarre, la boca del bebé está bien abierta, los labios evertidos y la mayor parte de la areola dentro de la boca.',
  'Doğru takılmış ve yaşa uygun oto koltuğu trafik kazalarında ölüm ve ağır yaralanma riskini büyük ölçüde azaltır.': 'Una silla de coche adecuada a la edad y bien instalada reduce mucho el riesgo de muerte y lesiones graves en accidentes.',
  'Doğru temizlik, ayırma, pişirme ve soğutma gıda kaynaklı hastalıkları önler.': 'Limpiar, separar, cocinar y enfriar correctamente previene las enfermedades por alimentos.',
  'Doğru yolda Harun': 'Harún en el buen camino',
  'Doğrudan yetişkin gözetiminin yerini almaz.': 'No sustituye la vigilancia directa de un adulto.',
  'Doğruyu ayıran Ali': 'Ali que distingue la verdad',
  'Doğruyu ayıran Ömer': 'Omar que distingue la verdad',
  'Doğruyu eğriden ayıran': 'El que distingue lo justo de lo injusto',
  'Doğruyu yanlıştan ayıran; Kur’an': 'Lo que separa la verdad del error; el Corán',
  'Doğum': 'Parto',
  'Doğum Sonrası': 'Después del parto',
  'Doğum Sonrası & Annelik': 'Posparto y maternidad',
  'Doğum ağrısıyla baş etmek için ilaçsız ve ilaçlı birçok yöntem vardır.': 'Hay muchas formas, con y sin medicamentos, de afrontar el dolor del parto.',
  'Doğum başlamazsa doktorunun izlem planını öğren; genellikle 41. haftada değerlendirme yapılır.': 'Si el parto no empieza, infórmese del plan de seguimiento de su médico; normalmente se hace una valoración en la semana 41.',
  'Doğum başlangıcı belirtileri': 'Señales del inicio del parto',
  'Doğum bekleniyor': 'Parto previsto',
  'Doğum belirtilerini ve ne zaman hastaneye gideceğini gözden geçir.': 'Repase las señales de parto y cuándo ir al hospital.',
  'Doğum günleri': 'Cumpleaños',
  'Doğum hazırlık eğitimleri bilinmezliği azaltabilir.': 'Las clases de preparación al parto pueden reducir la incertidumbre.',
  'Doğum hazırlık eğitimleri nefes ve gevşeme tekniklerini öğrenmeye yardımcı olur.': 'Las clases de preparación ayudan a aprender técnicas de respiración y relajación.',
  'Doğum hazırlık sınıflarına katılmayı düşün.': 'Valore asistir a clases de preparación al parto.',
  'Doğum hazırlık sınıflarını araştır.': 'Infórmese sobre las clases de preparación al parto.',
  'Doğum izni ve çalışan anne hakları': 'Baja por maternidad y derechos de las madres trabajadoras',
  'Doğum kasılmalarının süresi ve aralığı': 'Duración y frecuencia de las contracciones',
  'Doğum planı': 'Plan de parto',
  'Doğum planı esnek olmalıdır; tıbbi durum değişebilir.': 'El plan de parto debe ser flexible; la situación médica puede cambiar.',
  'Doğum planı ve hazırlık': 'Plan de parto y preparación',
  'Doğum planı, doğumla ilgili tercihlerini ekiple paylaşmanı kolaylaştıran kısa bir nottur.': 'El plan de parto es una nota breve que ayuda a compartir sus preferencias con el equipo.',
  'Doğum referansı eksik': 'Falta la referencia de nacimiento',
  'Doğum sonrası': 'Después del parto',
  'Doğum sonrası bakım': 'Cuidados posparto',
  'Doğum sonrası bakım ekranları': 'Pantallas de cuidados posparto',
  'Doğum sonrası depresyon her 7–10 anneden birinde görülür ve tedavi edilebilir.': 'La depresión posparto afecta a 1 de cada 7–10 madres y tiene tratamiento.',
  'Doğum sonrası destek': 'Apoyo posparto',
  'Doğum sonrası dikişler genellikle birkaç haftada iyileşir; temizlik ve dinlenme iyileşmeyi destekler.': 'Los puntos tras el parto suelen curar en unas semanas; la higiene y el descanso ayudan.',
  'Doğum sonrası doğum kontrolü': 'Anticoncepción tras el parto',
  'Doğum sonrası duygusal dalgalanmalar görülebilir. Yoğun üzüntü, kaygı veya işlev kaybı sürüyorsa profesyonel destek alın. Kendinize veya bebeğe zarar verme düşüncesinde acil yardım isteyin.': 'Los altibajos emocionales son frecuentes después del parto. Busca apoyo profesional si la tristeza intensa, la ansiedad o la dificultad para funcionar persisten. Pide ayuda urgente si tienes pensamientos de hacerte daño a ti o a tu bebé.',
  'Doğum sonrası günlük': 'Diario posparto',
  'Doğum sonrası hüzün ve depresyon': 'Tristeza posparto y depresión posparto',
  'Doğum sonrası idrar kaçırma yaygındır ve çoğu zaman tedavi edilebilir.': 'Los escapes de orina tras el parto son frecuentes y a menudo tratables.',
  'Doğum sonrası ilk saat: ten tene temas': 'La primera hora tras el parto: piel con piel',
  'Doğum sonrası kontrol genellikle 6. haftada yapılır; daha erken kontroller de önerilebilir.': 'La revisión posparto suele ser a las 6 semanas; también pueden recomendarse controles antes.',
  'Doğum sonrası kontrol randevumu planladım': 'He planificado mi control posparto',
  'Doğum sonrası kontrolde yöntem seçeneklerini hekiminle konuş.': 'Comente las opciones con su médico en la revisión posparto.',
  'Doğum sonrası kontrolleri sağlık ekibinizle planlayın. Kanama, ağrı, ilaçlar, korunma ve emzirme ile ilgili sorularınızı not edin.': 'Planifica los controles posparto con tu equipo de salud. Anota tus preguntas sobre el sangrado, el dolor, los medicamentos, la anticoncepción y la lactancia.',
  'Doğum sonrası korse': 'Faja posparto',
  'Doğum sonrası ve annelik': 'Posparto y maternidad',
  'Doğum sonrası yaklaşık {0}. gün • {1}. hafta': 'Aproximadamente el día {0} tras el parto • semana {1}',
  'Doğum sırasında ihtiyaçlarını ekibe açıkça söyle.': 'Diga claramente al equipo lo que necesita durante el parto.',
  'Doğum tarihi': 'Fecha de nacimiento',
  'Doğum tarihi eklenmedi': 'No se añadió fecha de nacimiento',
  'Doğum tarihi gelecekte olamaz.': 'La fecha de nacimiento no puede ser futura.',
  'Doğum tarihi girildiğinde bebeğin ayına göre açılır': 'Se abre según la edad de tu bebé al ingresar la fecha de nacimiento',
  'Doğum tarihi girilmedi: tüm yaş grupları gösteriliyor.': 'Sin fecha de nacimiento: se muestran todos los grupos de edad.',
  'Doğum tarihi seç': 'Elegir fecha de nacimiento',
  'Doğum tarihi seçilmelidir.': 'Debe seleccionarse una fecha de nacimiento.',
  'Doğum tarihi: {0}': 'Fecha de nacimiento: {0}',
  'Doğum tarihi: {0}.{1}.{2}': 'Fecha de nacimiento: {0}.{1}.{2}',
  'Doğum tarihim (yaşa uygun kontroller için)': 'Mi fecha de nacimiento (para controles según la edad)',
  'Doğum tarihim: {0}': 'Mi fecha de nacimiento: {0}',
  'Doğum tarihinden önceki kayıt': 'Registro anterior a la fecha de nacimiento',
  'Doğum tarihini düzenle': 'Editar fecha de nacimiento',
  'Doğum tarihini seç': 'Elegir fecha de nacimiento',
  'Doğum tarihini “Anne profilim”e girersen yaşına uygun kontroller gösterilir.': 'Si ingresas tu fecha de nacimiento en «Mi perfil», se muestran los controles adecuados a tu edad.',
  'Doğum tercihlerini (doğum planı) yazmaya başla.': 'Empiece a escribir sus preferencias para el parto (plan de parto).',
  'Doğum tercihlerini ve sorularını önceden hekiminle konuş.': 'Comente con antelación sus preferencias y dudas con su médico.',
  'Doğum yapacağın hastanenin acil iletişim bilgilerini telefonuna kaydet.': 'Guarde en su móvil los datos de contacto de urgencias del hospital donde dará a luz.',
  'Doğum yapacağın hastaneyi ve ulaşımı netleştir.': 'Confirme el hospital donde dará a luz y cómo llegará.',
  'Doğum yeri, ulaşım ve destek kişini planla.': 'Planifique dónde dará a luz, el transporte y su acompañante.',
  'Doğum çantasını hazırla': 'Prepara tu bolsa para el hospital',
  'Doğum şekli anne ve bebeğin durumuna göre hekimle birlikte planlanır.': 'La forma de dar a luz se planifica con su médico según su estado y el de su bebé.',
  'Doğum şekline göre iyileşme farklılık gösterir. Ağrı, kanama, yara bakımı ve hareket konusunda taburculuk önerilerini takip edin. Dinlenme için yakınlarınızdan destek isteyin.': 'La recuperación varía según el tipo de parto. Sigue las indicaciones del alta sobre el dolor, el sangrado, el cuidado de la herida y el movimiento. Pide apoyo a tus seres queridos para poder descansar.',
  'Doğum, nüfus müdürlüğüne yasal süre içinde bildirilmelidir; hastanelerde çoğu zaman doğum bildirimi elektronik yapılır.': 'El nacimiento debe inscribirse en el plazo legal; los hospitales a menudo lo comunican electrónicamente.',
  'Doğum: {0}': 'Nacimiento: {0}',
  'Doğum: {0}.{1}.{2}': 'Nacimiento: {0}.{1}.{2}',
  'Doğuma hazırlık listesi': 'Lista de preparación para el parto',
  'Doğuma yakın dönem: doğum belirtileri ve başvuru planını sağlık ekibinle netleştir.': 'Cerca de la fecha: aclara con tu equipo de salud los signos del parto y cuándo ir al hospital.',
  'Doğumda ağrı yönetimi': 'Alivio del dolor en el parto',
  'Doğumdan aylar sonra süren idrar veya gaz kaçırma.': 'Escapes de orina o gases que continúan meses después del parto.',
  'Doğumdan hemen sonra ten tene temas ve ilk saatte emzirme anne ve bebeğe birçok fayda sağlar.': 'El contacto piel con piel justo después del parto y la lactancia en la primera hora aportan muchos beneficios a la madre y al bebé.',
  'Doğumdan sonra işe dönüş hem duygusal hem pratik bir geçiştir; önceden planlamak kolaylaştırır.': 'Volver al trabajo tras el parto es una transición emocional y práctica; planificar con tiempo ayuda.',
  'Doğumdan sonra nüfus kaydı ve sağlık güvencesi işlemlerinin zamanında yapılması gerekir.': 'Tras el nacimiento hay que hacer a tiempo los trámites del registro civil y del seguro de salud.',
  'Doğumdan sonraki ilk 6 hafta vücudun toparlandığı, dinlenme ve desteğin en çok gerektiği dönemdir.': 'Las primeras 6 semanas tras el parto son cuando su cuerpo se recupera y más necesita descanso y apoyo.',
  'Doğumdan sonraki ilk adet gelmeden de gebelik oluşabilir.': 'Puede quedarse embarazada incluso antes de la primera regla tras el parto.',
  'Doğumdan sonraki ilk günlerde hüzün yaygındır; iki haftadan uzun süren belirtiler depresyon olabilir.': 'Sentirse decaída los primeros días tras el parto es frecuente; síntomas de más de dos semanas pueden ser depresión.',
  'Doğumdan sonraki ilk günlerde topuk kanı ve işitme taraması yapılır; 3–5. günde ilk kontrol önerilir.': 'En los primeros días se hacen la prueba del talón y el cribado auditivo; se recomienda una primera revisión entre el día 3 y 5.',
  'Doğumdan sonraki ilk hafta içinde topuk kanı taraması ve işitme taraması yapılır.': 'En la primera semana tras el nacimiento se hacen la prueba del talón y el cribado auditivo.',
  'Doğumdan sonraki ilk kontrolü (genellikle 3–5. gün) aksatma.': 'No falte a la primera revisión tras el parto (normalmente entre el día 3 y 5).',
  'Doğumdan sonraki kontrolleri aksatma.': 'No falte a las revisiones tras el parto.',
  'Doğu’nun hanı': 'Kan de Oriente',
  'Dudak kremi': 'Bálsamo labial',
  'Dudak veya yüzde morarma, nefes durmaları: 112.': 'Labios o cara azulados, pausas respiratorias: llame al número de emergencias local.',
  'Dudak/dil şişmesi, nefes darlığı, hırıltı, yaygın kurdeşen, bilinç değişikliği: 112.': 'Hinchazón de labios/lengua, falta de aire, pitidos, urticaria generalizada, alteración de la conciencia: llame al número de emergencias local.',
  'Duman dedektörü': 'Detector de humo',
  'Duran, kalıcı': 'Firme, duradero',
  'Duru, saf': 'Clara, pura',
  'Durum sunucudan doğrulandı.': 'Estado verificado con el servidor.',
  'Duvara düşen gölgeleri birlikte inceleyin.': 'Observen juntos las sombras en la pared.',
  'Duygu aynası': 'Espejo de emociones',
  'Duygu kartları': 'Tarjetas de emociones',
  'Duygu ve rutinler': 'Emociones y rutinas',
  'Duyguları adlandırma': 'Poner nombre a las emociones',
  'Duyguları adlandırma ("kızgın mısın?"), rol oyunları, açık havada tırmanma (alçak ve güvenli).': 'Poner nombre a las emociones («¿estás enfadado?»), juego de roles, trepar al aire libre (bajo y seguro).',
  'Duyguları adlandırmasına yardım et ("kızgın görünüyorsun").': 'Ayúdele a poner nombre a sus emociones («pareces enfadado»).',
  'Duygularını güvendiğin biriyle paylaş; yardım istemek güçlü bir adımdır.': 'Comparta lo que siente con alguien de confianza; pedir ayuda es un paso valiente.',
  'Duygularını paylaşabileceğin kişilerle konuş.': 'Hable con personas con las que pueda compartir lo que siente.',
  'Duyu': 'Sentidos',
  'Duyular gelişir; dokunmayı hissedebilir, kaşları belirir.': 'Se desarrollan los sentidos; su bebé siente el tacto y aparecen las cejas.',
  'Duyusal algı gelişir; hızla kilo alır.': 'Se desarrolla la percepción sensorial; su bebé gana peso rápido.',
  'Döküntü, dudak/dil şişmesi, kusma veya nefes darlığı: alerji, acil olabilir.': 'Erupción, hinchazón de labios/lengua, vómitos o falta de aire: alergia, puede ser una urgencia.',
  'Döllenmiş yumurta (zigot) hızla bölünerek rahme doğru ilerler.': 'El óvulo fecundado (cigoto) se divide rápidamente mientras avanza hacia el útero.',
  'Döngü Takibi': 'Seguimiento del ciclo',
  'Döngü değişimi, cilt ve diğer belirtileri hekiminizle görüşmek için not edin.': 'Anota los cambios del ciclo, de la piel y otros síntomas para hablarlos con tu médico.',
  'Döngü kayıtları': 'Registros del ciclo',
  'Döngü süresi: ortalama {0} gün ({1} kayıttan)': 'Duración del ciclo: promedio de {0} días (de {1} registros)',
  'Döngü süresi: {0} gün (varsayılan; daha fazla kayıt girince ölçülür)': 'Duración del ciclo: {0} días (por defecto; se medirá cuando ingreses más registros)',
  'Döngü uzunluğu (gün)': 'Duración del ciclo (días)',
  'Döngü ve belirtiler': 'Ciclo y síntomas',
  'Döngü • Sağlık': 'Ciclo • Salud',
  'Döngü, gebelik, doğum sonrası ve belirtiler': 'Ciclo, embarazo, posparto y síntomas',
  'Döngü, gebelik, doğum sonrası ve kontrol notları': 'Ciclo, embarazo, posparto y notas de control',
  'Döngü, gebelik, doğum sonrası ve menopoz notları': 'Ciclo, embarazo, posparto y notas de menopausia',
  'Döngünün sürekli 21 günden kısa veya 35 günden uzun olması.': 'Ciclos que son siempre de menos de 21 días o de más de 35.',
  'Dönüşten 2–3 hafta önce bakım düzenini denemeye başla.': 'Empiece a probar el cuidado 2–3 semanas antes de volver.',
  'Dördüncü; ilkbahar': 'Cuarta; primavera',
  'Dün, ': 'Ayer, ',
  'Dünya': 'El mundo',
  'Dünya mutfağı': 'Cocina del mundo',
  'Dünyaya önem vermeyen, sofu': 'Desprendido del mundo, asceta',
  'Dünyayı fetheden': 'Conquistador del mundo',
  'Dürüst han': 'Kan honesto',
  'Düzenle': 'Editar',
  'Düzenleyen; şair': 'El que ordena; poeta',
  'Düzenli ana ve ara öğün fırsatları sunun; açlık-tokluk işaretlerine saygı gösterin. Üzüm, sert kuruyemiş ve benzeri boğulma risklerini uygun şekilde hazırlayın.': 'Ofrezca comidas y tentempiés regulares; respete las señales de hambre y saciedad. Prepare de forma adecuada las uvas, los frutos secos duros y otros alimentos con riesgo de atragantamiento.',
  'Düzenli egzersiz ve dengeli beslenme belirtileri azaltabilir.': 'El ejercicio regular y una dieta equilibrada pueden reducir los síntomas.',
  'Düzenli egzersiz, kalsiyum ve D vitamini açısından zengin beslenme.': 'Ejercicio regular y una dieta rica en calcio y vitamina D.',
  'Düzenli egzersiz, yeterli uyku, tuz ve kafeini azaltmak yardımcı olabilir.': 'El ejercicio regular, dormir lo suficiente y reducir la sal y la cafeína pueden ayudar.',
  'Düzenli harcamaları ve yaklaşan ihtiyaçları yazın. Alışveriş öncesinde evdeki stokları kontrol edin.': 'Anote los gastos habituales y las necesidades próximas. Revise lo que tiene en casa antes de comprar.',
  'Düzenli hareket, uyku ve dengeli beslenme duygudurumu destekler.': 'El ejercicio regular, el sueño y una dieta equilibrada ayudan al ánimo.',
  'Düzenli kontrol et; çatlak veya yıpranmışsa değiştir.': 'Revíselo con regularidad; cámbielo si está agrietado o gastado.',
  'Düzenli kontrol planı': 'Plan de revisiones periódicas',
  'Düzenli kullandığım ilaçlar': 'Medicamentos que tomo habitualmente',
  'Düzenli uyku ve uyanma saatlerini not edin; çocuğun ihtiyaçlarına göre rutini uyarlayın.': 'Anote los horarios regulares de sueño y vigilia; adapte la rutina a las necesidades de su hijo.',
  'Düzenli ve giderek sıklaşan kasılmalar, su gelmesi ve nişan gelmesi doğumun başladığını gösterebilir.': 'Las contracciones regulares y cada vez más seguidas, la rotura de aguas y el tapón mucoso pueden indicar que empieza el parto.',
  'Düzenli yürüyüş gibi bir egzersiz rutini oluştur.': 'Cree una rutina de ejercicio, como paseos regulares.',
  'Düzenli, hafif-orta egzersiz (yürüyüş, yüzme, gebe yogası) faydalıdır.': 'El ejercicio regular de ligero a moderado (caminar, nadar, yoga prenatal) es beneficioso.',
  'Düzensiz adet, androjen fazlalığı belirtileri ve yumurtalıklarda çok sayıda küçük folikülle seyreden yaygın bir hormonal durumdur.': 'Un trastorno hormonal frecuente con reglas irregulares, signos de exceso de andrógenos y muchos folículos pequeños en los ovarios.',
  'Düzensiz adet, kronik hastalık veya önceki gebelik kayıpları varsa erkenden.': 'Pronto, si tiene reglas irregulares, una enfermedad crónica o pérdidas de embarazo previas.',
  'Düzensiz ve düzenli kasılmaları ayırt etmeye çalış.': 'Intente distinguir las contracciones irregulares de las regulares.',
  'Düzensiz veya hiç adet görmeme, bilinen tüp veya rahim sorunu.': 'Reglas irregulares o ausentes, problema conocido de trompas o útero.',
  'Düzensiz veya seyrek adet, sivilce, tüylenme ve kilo artışı görülebilir.': 'Pueden aparecer reglas irregulares o escasas, acné, exceso de vello y aumento de peso.',
  'Düzleşme 4 aydan sonra artıyorsa veya alın/kulaklarda asimetri varsa.': 'Si el aplanamiento aumenta después de los 4 meses o la frente/las orejas están asimétricas.',
  'Düğme pil veya mıknatıs yutma şüphesi: hemen acil servis.': 'Sospecha de que ha tragado una pila de botón o un imán: vaya a urgencias de inmediato.',
  'Düğme pilleri ve mıknatısları çocuklardan uzak tut.': 'Mantenga las pilas de botón y los imanes lejos de los niños.',
  'Düş': 'Sueño',
  'Düşme sonrası diş kırığı veya yerinden çıkma: hemen diş hekimi.': 'Diente roto o caído tras una caída: acuda al dentista de inmediato.',
  'Düşme ve darbe riski olan sporlar ile sırtüstü uzun süre yatmayı gerektiren hareketler önerilmez.': 'No se recomiendan deportes con riesgo de caída o golpe ni ejercicios que exijan estar tumbada boca arriba mucho tiempo.',
  'Düşme ve kafa travması': 'Caídas y golpes en la cabeza',
  'Düşmeler, zehirlenmeler, yanıklar ve boğulma en sık ev kazalarıdır.': 'Caídas, intoxicaciones, quemaduras y ahogamientos son los accidentes domésticos más frecuentes.',
  'Düştükten sonra birkaç gün az miktarda kanlı lekelenme olabilir.': 'Tras la caída es posible un ligero sangrado durante unos días.',
  'Düşük ışıklı gece aydınlatması.': 'Luz nocturna tenue.',
  'Düşüklerin çoğu ilk 12 haftada ve genellikle kromozom farklılıklarına bağlı olarak gerçekleşir.': 'La mayoría de los abortos espontáneos ocurren en las primeras 12 semanas, generalmente por alteraciones cromosómicas.',
  'Düşünce': 'Pensamiento',
  'DİKKAT: Yedekte bulunan alanlardaki mevcut kayıtlar yedekteki değerlerle değiştirilecek. Yedekte olmayan alanlardaki kayıtlar korunur. İşlem öncesi yine de mevcut verilerinizi ayrıca yedekleyin.': 'ADVERTENCIA: Los registros existentes en los campos incluidos en la copia se reemplazarán por los valores de la copia. Los registros de campos no incluidos se conservan. Aun así, haz una copia de tus datos actuales por separado antes de continuar.',
  'DİKKAT: Çocuk 49–72 aylık yakalama aşılaması yaş grubunda olabilir. İkinci suçiçeği dozu için aile hekiminizle görüşün. Bu uyarı aşı yapılmadığı anlamına gelmez.': 'NOTA: El niño puede estar en el grupo de vacunación de rescate de 49 a 72 meses. Habla con tu médico de familia sobre la segunda dosis de varicela. Esta advertencia no significa que no se haya puesto la vacuna.',
