  'Göz muayenesi': 'Examen ocular',
  'Göz teması kurmama, adına tepki vermeme, işaret etmeme.': 'No mantiene contacto visual, no responde a su nombre, no señala.',
  'Göz teması kurmama, adına tepki vermeme.': 'No mantiene contacto visual, no responde a su nombre.',
  'Göz ve işitme taramalarını aksatma.': 'No falte a las revisiones de vista y oído.',
  'Göz çapağını kaynatılıp soğutulmuş suya batırılmış temiz pamukla içten dışa sil.': 'Limpie los ojos pegados de dentro hacia fuera con algodón limpio mojado en agua hervida y enfriada.',
  'Göz, göz bebeği': 'Ojo, niña de los ojos',
  'Gözde kızarıklık ve yoğun sarı-yeşil çapak; yenidoğanda her zaman değerlendirilmeli.': 'Ojo rojo con secreción espesa amarillo-verdosa; en el recién nacido siempre hay que consultar.',
  'Göze veya cilde temas ettiyse bol suyla en az 15 dakika yıka.': 'Si le cayó en los ojos o la piel, aclare con abundante agua al menos 15 minutos.',
  'Gözetimli yüzüstü oyun': 'Tiempo boca abajo vigilado',
  'Gözler açılmaya başlar; seslere tepki verebilir.': 'Los ojos empiezan a abrirse; su bebé puede reaccionar a los sonidos.',
  'Gözler açılıp kapanabilir. Üçüncü trimester başlar.': 'Los ojos pueden abrirse y cerrarse. Empieza el tercer trimestre.',
