  'Günlük hareket, iletişim ve oyun gözlemlerinizi kaydedin. Gelişim hızı çocuklar arasında değişebilir.': 'Registra tus observaciones diarias de movimiento, comunicación y juego. El ritmo de desarrollo varía de un niño a otro.',
  'Günlük hareketliliğe uygun kumaş ve kalıpları seçin. Mevsim ve gün içindeki sıcaklık değişimine göre katmanlı giyinin.': 'Elija tejidos y cortes adecuados a su actividad diaria. Vístase por capas según la estación y los cambios de temperatura.',
