  'Günün sevilen anlarını kısa cümlelerle paylaşın.': 'Compartan en frases cortas los momentos favoritos del día.',
  'Günün sonunda nasıl hissettiğinizi birkaç kelimeyle yazın. Duygunuzu değiştirmeye zorlamadan fark etmeye çalışın.': 'Al final del día, escriba en pocas palabras cómo se siente. Intente notar la emoción sin obligarse a cambiarla.',
