  'Güvenli bir alanda kısa yürüyüş yapın. Çevredeki sesleri, renkleri ve kokuları fark etmeye odaklanın.': 'Dé un paseo corto por un lugar seguro. Concéntrese en notar los sonidos, colores y olores a su alrededor.',
