  'Güvenli uyku ortamı': 'Entorno de sueño seguro',
  'Güvenli uyku rehberlerine uyun; yumuşak nesnelerden kaçının.': 'Siga las recomendaciones de sueño seguro; evite objetos blandos.',
  'Güvenli uyku, bal, şeker ve ekran gibi konularda öneriler zaman içinde değişmiştir.': 'Las recomendaciones sobre sueño seguro, miel, azúcar y pantallas han cambiado con el tiempo.',
  'Güvenli veri taşıma doğrulanamadı: {0}': 'No se pudo verificar la transferencia segura de datos: {0}',
