  'Sağılan anne sütü doğru saklandığında besin değerini korur.': 'La leche materna extraída conserva su valor nutritivo si se guarda bien.',
  'Sağılmış süt saklama ekipmanı.': 'Material para guardar la leche extraída.',
  'Sebze': 'Verduras',
  'Sebze ağırlıklı': 'A base de verduras',
  'Sebze seçenekleri': 'Opciones de verduras',
  'Sebze ve kaşarı tabana yayın, sıvı karışımı dökün.': 'Reparta las verduras y el kaşar sobre la base y vierta la mezcla líquida.',
  'Sebze ve meyve': 'Frutas y verduras',
  'Sebze ve meyveleri iyice yıka; eti tam pişir.': 'Lave bien frutas y verduras; cocine bien la carne.',
  'Sebze yemekleri': 'Platos de verduras',
  'Sebze çubukları ve tahinli dip': 'Palitos de verdura con salsa de tahini',
  'Sebze çubuklarıyla.': 'Con palitos de verdura.',
  'Sebze, meyve, protein ve tahıllarda çeşitlilik sağlayın. Çocuğu yemek hazırlığına yaşına uygun görevlerle katın; zorla yedirmekten kaçının.': 'Dé variedad de verduras, frutas, proteínas y cereales. Implique a su hijo en preparar la comida con tareas adecuadas a su edad; evite obligarle a comer.',
  'Sebze, meyve, tam tahıl, baklagil ve yeterli protein içeren dengeli öğünler hazırla.': 'Prepare comidas equilibradas con verduras, fruta, cereales integrales, legumbres y suficiente proteína.',
  'Sebze, meyve, tam tahıl, protein ve süt ürünlerinden çeşitlilik sun. Ne yiyeceğine sen, ne kadar yiyeceğine çocuk karar versin. Şekerli içecekleri ve paketli atıştırmalıkları sınırla.': 'Ofrezca variedad de verduras, frutas, cereales integrales, proteínas y lácteos. Usted decide qué se come; el niño, cuánto. Limite las bebidas azucaradas y los snacks envasados.',
  'Sebzeler buzdolabında 2 gün.': 'Las verduras se conservan 2 días en la nevera.',
  'Sebzeler ve et tamamen yumuşayana kadar 20–25 dakika daha pişirin.': 'Cocine 20–25 minutos más hasta que verduras y carne estén muy tiernas.',
  'Sebzeler ve et tamamen yumuşayana kadar yaklaşık 25 dakika daha pişirin.': 'Cocine unos 25 minutos más hasta que verduras y carne estén muy tiernas.',
  'Sebzeler yumuşayınca tavuk parçalarını geri koyun.': 'Cuando las verduras estén tiernas, vuelva a añadir el pollo.',
  'Sebzeler yumuşayıncaya kadar yaklaşık 20 dakika pişirin.': 'Cocine unos 20 minutos hasta que las verduras estén tiernas.',
  'Sebzeleri bardaklara dizin.': 'Coloque las verduras en vasos.',
  'Sebzeleri ekleyip iki dakika çevirin.': 'Añada las verduras y remueva dos minutos.',
  'Sebzeleri enginarların içine yerleştirip zeytinyağı ve az su ekleyin.': 'Coloque las verduras dentro de las alcachofas y añada aceite y un poco de agua.',
  'Sebzeleri eşit boyutta doğrayın ki aynı anda pişsin.': 'Corte las verduras del mismo tamaño para que se hagan a la vez.',
  'Sebzeleri eşit büyüklükte doğrayın.': 'Corte las verduras del mismo tamaño.',
  'Sebzeleri fırın kabına yayıp üzerine balıkları yerleştirin.': 'Extienda las verduras en una fuente y coloque el pescado encima.',
  'Sebzeleri ince dilimleyip yağla harmanlayın.': 'Corte las verduras en láminas finas y mézclelas con aceite.',
  'Sebzeleri ince doğrayın ki balıkla aynı sürede pişsin.': 'Corte las verduras finas para que se hagan al mismo tiempo que el pescado.',
  'Sebzeleri ince doğrayıp bir kapta karıştırın.': 'Pique las verduras finas y mézclelas en un bol.',
  'Sebzeleri ince doğrayıp tepsiye yayın.': 'Corte las verduras finas y extiéndalas en la bandeja.',
  'Sebzeleri iyice yıkayın.': 'Lave bien las verduras.',
  'Sebzeleri karıştırıp servis tabağına alın.': 'Mezcle las verduras y páselas a una fuente.',
  'Sebzeleri küp doğrayıp ayrı ayrı fırında yumuşatın.': 'Corte las verduras en dados y ablándelas por separado en el horno.',
  'Sebzeleri küçük doğrayıp kabağı hafifçe sıkın.': 'Pique las verduras y escurra ligeramente el calabacín.',
  'Sebzeleri küçük doğrayıp yağda yumuşayana dek soteleyin.': 'Pique las verduras y saltéelas en aceite hasta que estén tiernas.',
  'Sebzeleri küçük küpler hâlinde doğrayın.': 'Corte las verduras en daditos.',
  'Sebzeleri soyup eşit kalınlıkta dilimleyin.': 'Pele las verduras y córtelas del mismo grosor.',
  'Sebzeleri soyup uygun uzunlukta kesin.': 'Pele las verduras y córtelas en bastones de largo adecuado.',
  'Sebzeleri yağda 8-10 dakika yumuşayana kadar soteleyin.': 'Saltee las verduras 8-10 minutos hasta que estén tiernas.',
  'Sebzeleri yağda birkaç dakika çevirin.': 'Saltee las verduras en aceite unos minutos.',
  'Sebzeleri yumuşayana kadar pişirin.': 'Cueza las verduras hasta que estén blandas.',
  'Sebzeleri yıkayın.': 'Lave las verduras.',
  'Sebzeleri yıkayıp parmak kalınlığında çubuklar hâlinde kesin.': 'Lave las verduras y córtelas en palitos del grosor de un dedo.',
  'Sebzeleri zeytinyağında birkaç dakika çevirin.': 'Saltee las verduras en aceite de oliva unos minutos.',
  'Sebzeleri zeytinyağında yumuşayana kadar soteleyin.': 'Saltee las verduras en aceite de oliva hasta que estén tiernas.',
  'Sebzeleri, limon suyunu ve yağı ekleyip servis edin.': 'Añada las verduras, el limón y el aceite y sirva.',
  'Sebzeleri, mısırı ve ton balığını kasede birleştirin.': 'Junte las verduras, el maíz y el atún en un bol.',
  'Sebzelerin yarısını her kâğıdın ortasına yayın; alabalıkları tuz ve karabiberle ovup sebzelerin üzerine koyun.': 'Reparta la mitad de las verduras en el centro de cada papel; frote las truchas con sal y pimienta y colóquelas encima.',
