  'Ses taklidi': 'Imitar sonidos',
  'Ses telleri gelişir; bağırsaklar karın içindeki yerine yerleşir.': 'Se desarrollan las cuerdas vocales; los intestinos se colocan en el abdomen.',
  'Ses veya görüntü izleme ekipmanı.': 'Equipo de vigilancia con audio o vídeo.',
  'Ses çalınamadı. Telefonun sessiz modda olmadığını kontrol edip tekrar deneyin.': 'No se pudo reproducir el sonido. Comprueba que el teléfono no esté en silencio e inténtalo de nuevo.',
  'Ses çıkaramıyor, nefes alamıyor veya morarıyorsa hemen müdahale gerekir.': 'Si no puede hacer ruido, no respira o se pone azul, actúe de inmediato.',
  'Ses, yankı': 'Voz, eco',
  'Sesi farklı yönlerden duyurarak dikkatini takip edin.': 'Haga sonar el juguete desde distintas direcciones y siga su atención.',
  'Sesin yönünü bul': 'Encontrar de dónde viene el sonido',
  'Sesiniz': 'Su voz',
  'Sesler uygulama içinde matematiksel olarak üretilir. Brahms Ninnisi (1868) ve “Parla Parla Küçük Yıldız” ezgisi kamu malıdır; “Uyku melodisi” bu uygulama için bestelenmiştir.': 'Los sonidos se generan matemáticamente dentro de la app. La Canción de cuna de Brahms (1868) y la melodía de «Estrellita, ¿dónde estás?» son de dominio público; la «Melodía del sueño» se compuso para esta app.',
