  'Seyahat sırasında kanama, su gelmesi veya düzenli kasılmalar.': 'Sangrado, pérdida de líquido o contracciones regulares durante el viaje.',
  'Seyahat yatağı': 'Cuna de viaje',
  'Seyahatten önce gebelik kartını ve tahlil sonuçlarını yanına al.': 'Lleve consigo su historial de embarazo y sus resultados al viajar.',
  'Sezaryen büyük bir karın ameliyatıdır; iyileşme genellikle 6–8 hafta sürer.': 'La cesárea es una cirugía abdominal mayor; la recuperación suele llevar 6–8 semanas.',
  'Sezaryen sonrası ağır kaldırmaktan kaçın; öksürürken karnını yastıkla destekle.': 'Tras una cesárea evite cargar peso; sujétese la barriga con un cojín al toser.',
  'Sezaryen sonrası emzirme mümkündür; yan yatarak veya koltuk altı pozisyonu rahat olabilir.': 'Dar el pecho tras una cesárea es posible; tumbada de lado o en posición de balón de rugby puede ser cómodo.',
  'Sezaryen sonrası iyileşme': 'Recuperación tras una cesárea',
  'Sezaryen sonrası tam iyileşme 6–8 hafta sürebilir.': 'La recuperación completa tras una cesárea puede llevar 6–8 semanas.',
  'Sezaryen tıbbi gerekliliklerde hayat kurtarıcıdır; büyük bir ameliyat olduğu için iyileşmesi daha uzundur.': 'La cesárea salva vidas cuando es médicamente necesaria; al ser una cirugía mayor, la recuperación es más larga.',
  'Sezaryenden sonra da çoğu zaman mümkündür.': 'A menudo también es posible tras una cesárea.',
  'Seçenek sun ("kırmızı mı mavi mi?") ve küçük görevler ver.': 'Ofrezca opciones («¿rojo o azul?») y encargue pequeñas tareas.',
  'Seçenek sunma ("elma mı muz mu?"), kutu içine şekil yerleştirme, birlikte toplama oyunu.': 'Ofrecer opciones («¿manzana o plátano?»), encajables de formas, recoger juntos como un juego.',
  'Seçenekleri ve hastanende uygulananları önceden öğren.': 'Infórmese antes de las opciones y de lo que ofrece su hospital.',
  'Seçilen çocuğun JSON yedeği panoya kopyalandı. Güvenli bir yerde saklayın.': 'La copia JSON del niño seleccionado se copió al portapapeles. Guárdala en un lugar seguro.',
