  'Sindirim sistemi gelişir; yuttuğu amniyon sıvısını işlemeye başlar.': 'Se desarrolla el aparato digestivo; empieza a procesar el líquido amniótico que traga.',
  'Siyah-beyaz kontrastlı kartlar, yüzünü yavaşça sağa-sola hareket ettirerek takip ettirme, günde birkaç kez karın üstü oyun.': 'Tarjetas de contraste en blanco y negro, mover despacio su cara de un lado a otro para que la siga, ratos boca abajo varias veces al día.',
