  'Soldan sağa: {0} – {1}': 'De izquierda a derecha: {0} – {1}',
  'Solukluk, halsizlik, iştahsızlık sürüyorsa.': 'Si la palidez, el cansancio o la falta de apetito continúan.',
  'Somon küplerini ekleyip 3–4 dakika, tüm yüzleri açık renge dönene kadar nazikçe çevirin.': 'Añada los dados de salmón y gírelos con cuidado 3–4 minutos hasta que se aclaren por todos lados.',
  'Somonları fırının orta rafında 15–18 dakika, eti çatalla kolayca ayrılana ve iç sıcaklığı 63 °C olana kadar pişirin.': 'Hornee en la bandeja central 15–18 minutos, hasta que la carne se separe fácilmente con el tenedor y llegue a 63 °C.',
  'Somonları sebzelerle tepsiye koyup limon sıkın.': 'Ponga el salmón en la bandeja con las verduras y exprima limón por encima.',
  'Somonları soğuk suyla durulayıp kâğıt havluyla iyice kurulayın; derili tarafı alta gelecek şekilde tepsiye dizin.': 'Enjuague el salmón con agua fría, séquelo con papel y colóquelo con la piel hacia abajo.',
  'Somonlu makarna': 'Pasta con salmón',
  'Somonu fazla karıştırmayın; parçalar bütün kalırsa daha güzel görünür.': 'No remueva demasiado el salmón; queda mejor si los trozos se mantienen enteros.',
  'Somonu pişirmeden 15 dakika önce buzdolabından çıkarırsanız daha eşit pişer.': 'Si saca el salmón de la nevera 15 minutos antes, se cocina de forma más uniforme.',
