  'Son bir saattir kasılmalar 5 dakikada bir geliyor ve en az 1 dakika sürüyor. Doktorunu ya da doğum yapacağın hastaneyi ara; sana söylenen plana göre yola çık.': 'Durante la última hora, las contracciones han llegado cada 5 minutos y han durado al menos 1 minuto. Llama a tu médico o al hospital donde darás a luz y sal según el plan que te dieron.',
