  'Son iki haftada birçok gün kendini kötü hissetmişsin. Bu yalnız taşıman gereken bir yük değil; bir yakınınla ya da doktorunla konuş. Kendine zarar verme düşüncesi varsa hemen 112’yi ara.': 'Te has sentido mal muchos días en las últimas dos semanas. No tienes que cargar con esto sola; habla con alguien cercano o con tu médico. Si tienes pensamientos de hacerte daño, llama de inmediato al número de emergencias local.',
