  'Tatlıyı ödül olarak kullanma; şekerli içecekleri sınırla.': 'No use dulces como premio; limite las bebidas azucaradas.',
  'Tava kalabalık olursa balık kızarmaz, haşlanır; gerekirse iki partide pişirin.': 'Si la sartén está llena, el pescado se cuece en vez de dorarse; hágalo en dos tandas si hace falta.',
  'Tavada orta ateşte iki yüzünü kızartın; kalınlığına göre 12–18 dakika pişirin.': 'Dore ambos lados a fuego medio; cocine 12–18 minutos según el grosor.',
  'Tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar çevirin.': 'Caliente el aceite y saltee el pollo a fuego fuerte hasta que se dore.',
  'Tavada zeytinyağıyla soğanı 3 dakika yumuşatın, salçayı ekleyip 1 dakika kavurun; rendelenmiş domatesi ve sıcak suyu ilave edip 3 dakika kaynatın.': 'Sofría la cebolla 3 minutos en aceite, añada el concentrado 1 minuto; agregue el tomate rallado y el agua caliente y hierva 3 minutos.',
