  'Telefon bildirimi isteğe bağlıdır ve izin gerektirir. Pil kısıtlamaları nedeniyle bildirim gecikebilir. Acil sağlık durumları veya ilaç takibi için tek başına kullanılmamalıdır.': 'Las notificaciones del teléfono son opcionales y requieren permiso. Pueden retrasarse por las restricciones de batería. No deben ser lo único en lo que confíes para emergencias médicas o el seguimiento de medicamentos.',
