  'Temmuz': 'Julio',
  'Ten tene temas bebeğin ısısını ve kalp atımını düzenler, emzirmeyi başlatmayı kolaylaştırır.': 'El piel con piel regula la temperatura y el latido del bebé y facilita el inicio de la lactancia.',
  'Ten tene temas, yüz yüze konuşma, ninni. Kısa süreli, uyanıkken gözetimli karın üstü zaman.': 'Piel con piel, hablarle cara a cara, nanas. Ratos cortos boca abajo, despierto y vigilado.',
  'Tencerede salça, sebzeler, mercimek ve suyu birleştirin.': 'Junte el concentrado, las verduras, las lentejas y el agua en una olla.',
  'Tencerede tereyağını eritip unu 1 dakika kavurun; sütü çırparak ekleyin ve kaynayıp hafif koyulaşana kadar 4 dakika karıştırın.': 'Derrita la mantequilla y tueste la harina 1 minuto; incorpore la leche batiendo y remueva 4 minutos hasta que hierva y espese un poco.',
  'Tencerede yağ ile havucu 3 dakika çevirin.': 'Sofría la zanahoria en aceite 3 minutos.',
  'Tencerede yağı ısıtıp soğan ve havucu 3 dakika çevirin.': 'Caliente el aceite y sofría la cebolla y la zanahoria 3 minutos.',
  'Tencereye dizip yarısına gelecek kadar su ekleyin; 35–40 dakika pişirin.': 'Colóquelos en una olla, añada agua hasta la mitad y cocine 35–40 minutos.',
  'Tencereye sebzeleri yerleştirip zeytinyağını ekleyin.': 'Coloque las verduras en una olla y añada el aceite de oliva.',
  'Tepsiye dizip içlerine az yağ ve peynir koyun.': 'Colóquelos en la bandeja y ponga dentro un poco de aceite y queso.',
  'Tepsiye tek kat yayıp 30 dakika, iki kez sallayarak çıtırlaşana kadar pişirin.': 'Extiéndalos en una capa y hornee 30 minutos, agitando dos veces, hasta que estén crujientes.',
  'Tepsiye üst üste gelmeyecek şekilde yayın.': 'Extiéndala en la bandeja sin amontonar.',
  'Terbiyeli tavuk çorbası': 'Sopa de pollo con liga de huevo y yogur',
  'Terbiyeyi tencereye döküp karıştırarak kaynatın; nane ekleyin.': 'Vierta la mezcla en la olla y lleve a ebullición removiendo; añada menta.',
  'Terbiyeyi tencereye karıştırarak dökün, birkaç dakika kaynatın.': 'Vierta la liga en la olla removiendo y hierva unos minutos.',
