  'Tercihlerini 1 sayfayı geçmeyecek şekilde yaz ve hekiminle konuş.': 'Escriba sus preferencias en 1 página como máximo y coméntelas con su médico.',
  'Tereyağı ve doğranmış çikolatayı ekleyip eriyene kadar karıştırın.': 'Añada la mantequilla y el chocolate troceado y remueva hasta que se fundan.',
  'Tereyağı ve unu kavurup sütü azar azar ekleyerek koyu sos hazırlayın.': 'Tueste la mantequilla y la harina y añada la leche poco a poco hasta obtener una salsa espesa.',
