  'Tereyağında unu 1 dakika kavurun, sütü azar azar ekleyerek koyulaştırın.': 'Tueste la harina 1 minuto en la mantequilla, añada la leche poco a poco y espese.',
  'Tereyağında unu 1 dakika kavurun, sütü çırparak ekleyip 3 dakika koyulaşana kadar pişirin.': 'Tueste la harina 1 minuto en la mantequilla, incorpore la leche batiendo y cocine 3 minutos hasta espesar.',
  'Tereyağında unu kavurup sütü azar azar ekleyerek koyulaştırın.': 'Tueste la harina en mantequilla y espese añadiendo la leche poco a poco.',
