  'Trafik, oyun alanı, su güvenliği ve yabancılarla sınırlar konusunda yaşa uygun konuşun. Bisiklet ve benzeri etkinliklerde uygun koruyucu ekipman kullanın.': 'Hable según su edad sobre el tráfico, los parques, la seguridad en el agua y los límites con desconocidos. Use protecciones adecuadas para la bici y actividades similares.',
