  'Türkiye\'de ALO 183 Sosyal Destek Hattı ve Kadın Destek Uygulaması (KADES) yardım sağlar.': 'En Türkiye ayudan la Línea de Apoyo Social ALO 183 y la aplicación de apoyo a la mujer (KADES).',
