  'Türkiye\'de ulusal programda 30–65 yaş arası kadınlara 5 yılda bir HPV testi ve smear önerilir.': 'En el programa nacional de Türkiye se recomienda una prueba de VPH y una citología cada 5 años a las mujeres de 30 a 65 años.',
