  'Un ve kabartma tozunu ekleyip pürüzsüz bir harç elde edene kadar karıştırın.': 'Añada la harina y la levadura y mezcle hasta obtener una masa lisa.',
  'Un ve kabartma tozunu karıştırıp kalıba dökün.': 'Incorpore la harina y la levadura química y vierta en el molde.',
  'Un ve suyla yumuşak bir hamur yoğurup 10 dakika dinlendirin.': 'Amase una masa suave con harina y agua y deje reposar 10 minutos.',
  'Un ve yağı ekleyip yumuşak hamur yoğurun, 45 dakika mayalandırın.': 'Añada la harina y el aceite, amase una masa suave y deje levar 45 minutos.',
  'Un, ceviz ve kabartma tozunu ekleyip yumuşak hamur elde edin.': 'Añada la harina, las nueces y la levadura química hasta obtener una masa suave.',
  'Un, kabartma tozu ve tarçını eleyerek ekleyin; cevizi un serpip ilave edin.': 'Tamice la harina, la levadura y la canela; enharine las nueces y añádalas.',
  'Un, tuz ve küp tereyağını parmak uçlarıyla ovalayın; yumurta ve suyu ekleyip toparlayın, 30 dakika buzdolabında dinlendirin.': 'Frote la harina, la sal y la mantequilla en dados con la punta de los dedos; añada el huevo y el agua, una y refrigere 30 minutos.',
  'Un, tuz ve tereyağını ovalayın, kaşarı ekleyin.': 'Frote la harina, la sal y la mantequilla y añada el kaşar.',
  'Un, şeker ve yulafı karıştırın, soğuk tereyağını ekleyip kum kıvamına gelene kadar ovalayın.': 'Mezcle la harina, el azúcar y la avena, añada la mantequilla fría y frote hasta obtener textura arenosa.',
  'Unları, maya, şeker ve tuzu karıştırın; su ve 2 yemek kaşığı zeytinyağıyla 8 dakika yoğurun.': 'Mezcle las harinas, la levadura, el azúcar y la sal; amase 8 minutos con el agua y 2 cucharadas de aceite.',
  'Unu azar azar ekleyip ele yapışmayan yumuşak bir hamur yoğurun.': 'Añada la harina poco a poco y amase una masa suave que no se pegue.',
  'Unu ekleyip bir dakika karıştırın; suyu azar azar ilave edin.': 'Añada la harina y remueva un minuto; agregue el agua poco a poco.',
  'Unu katıp kısa süre kavurun.': 'Incorpore la harina y tuéstela brevemente.',
  'Unutulan dozları iki kat vererek telafi etmeyin; ilaç özelindeki öneriyi eczacıya veya hekime sorun.': 'No compense las dosis olvidadas dando el doble; pida consejo específico al farmacéutico o al médico.',
  'Uskumru yağlı bir balıktır; ekstra yağ eklemeyin.': 'La caballa es un pescado graso; no añada aceite extra.',
