  'Uzanabileceği mesafede güvenli oyuncak, farklı dokular, sesli kitaplar. Konuşurken duraklayıp "cevap" vermesini bekle.': 'Juguetes seguros a su alcance, texturas distintas, libros con sonidos. Al hablarle, haga pausas y espere su «respuesta».',
  'Uzun araba yolculuklarında 2 saatte bir mola verilmesi önerilir.': 'En viajes largos en coche se recomienda una parada cada 2 horas.',
  'Uzun süre kullanım kulak iltihabı ve diş dizilimi sorunlarıyla ilişkilendirilmiştir.': 'El uso prolongado se relaciona con otitis y problemas de alineación dental.',
  'Uzun süreli yorgunluk, çocuktan duygusal uzaklaşma ve yetersizlik hissi ebeveyn tükenmişliğinin belirtileri olabilir.': 'El agotamiento prolongado, la distancia emocional con el hijo y la sensación de no llegar pueden ser signos de burnout parental.',
  'Uzun süren uykusuzluk için profesyonel destek alın.': 'Busque apoyo profesional ante un insomnio prolongado.',
  'Uzun ve güzel boyunlu': 'De cuello largo y hermoso',
  'Uzun yolculuklarda her 1–2 saatte bir yürü, bol su iç.': 'En viajes largos, camine cada 1–2 horas y beba mucha agua.',
