  'Uçak yolculuğu için en rahat dönem genellikle 14–28. haftalardır; havayolları geç dönemde rapor isteyebilir.': 'El momento más cómodo para volar suele ser entre las semanas 14 y 28; las aerolíneas pueden pedir certificado médico al final del embarazo.',
  'Uçakta kalkış ve inişte emzirmek veya biberon vermek kulak basıncını dengeler.': 'Dar el pecho o el biberón en el despegue y el aterrizaje ayuda a equilibrar la presión de los oídos.',
