  'Vücut kitle indeksi: {0} ({1}). Gebelikte ve emzirirken geçerli bir ölçüt değildir.': 'Índice de masa corporal: {0} ({1}). No es una medida válida durante el embarazo y la lactancia.',
  'Vücut ısısı düşük görünüyor. Bebeği ısıt, ölçümü tekrarla; düşük kalıyorsa ya da bebek halsizse hemen doktora başvur.': 'La temperatura parece baja. Abriga a tu bebé y vuelve a medir; si sigue baja o el bebé está decaído, acude al médico de inmediato.',
