  'WHO persentili için doğrulanmış CDC/WHO 0–24 ay CSV dosyaları gereklidir. Üstteki yükleme simgesiyle resmi CSV içeriğini panodan içe aktarabilirsiniz. Referans yüklenmeden persentil hesaplanmaz.': 'Para los percentiles de la OMS se necesitan archivos CSV CDC/OMS de 0–24 meses verificados. Puedes importar el contenido CSV oficial desde el portapapeles con el icono de carga de arriba. Sin referencia no se calculan percentiles.',
