  'Yaklaşık 6–10 sözcük; basit yönergeleri anlar. Kaşıkla yemekte daha becerikli, inatlaşma başlayabilir.': 'Unas 6–10 palabras; entiende órdenes sencillas. Más hábil con la cuchara; puede empezar la tozudez.',
