  'Yalnızca girilen tarihler arasındaki geçmiş aralıkları özetler. Tahmin veya doğum kontrolü amacıyla kullanmayın.': 'Solo resume los intervalos pasados entre las fechas que ingresaste. No lo uses para predicciones ni como anticonceptivo.',
  'Yalnızca izleme, dinleme ve nazik karşılıklı etkileşim kullanın; bebeği zorlamayın. Hareket ve nesne gerektiren adımları uygulamayın.': 'Use solo la mirada, la escucha y un intercambio suave; no fuerce al bebé. Omita los pasos que requieran movimiento u objetos.',
  'Yalnızca sayıyla başlayan ölçüler oransal hesaplanır. Kesirli, yaklaşık ve metin içindeki ölçüleri kontrol et.': 'Solo se recalculan proporcionalmente las cantidades que empiezan por un número. Revisa las fracciones, las cantidades aproximadas y las del texto.',
