  'Yağ gezdirip balık eti opaklaşana ve kolay ayrılana dek 25–30 dakika pişirin.': 'Rocíe aceite y hornee 25–30 minutos hasta que la carne esté opaca y se separe con facilidad.',
  'Yağ ve baharatla harmanlayıp tepsiye yayın.': 'Mezcle con aceite y especias y extienda en la bandeja.',
