  'Yağ ve kekiği ekleyip harmanlayın.': 'Añada el aceite y el tomillo y mezcle.',
  'Yağ ve limonla karıştırarak servis edin.': 'Mezcle con aceite y limón y sirva.',
  'Yağda kapak kapalı yumuşayana kadar pişirin.': 'Cocine tapado en aceite hasta que estén tiernas.',
