  'Yağda unu 1 dakika kavurup domatesi ekleyin.': 'Tueste la harina 1 minuto en aceite y añada el tomate.',
  'Yağda önce tavuğu, ardından soğan ve biberi soteleyin.': 'Saltee primero el pollo y luego la cebolla y el pimiento.',
  'Yağları tencerede ısıtıp pirinci 3 dakika kavurun.': 'Caliente la grasa en una olla y rehogue el arroz 3 minutos.',
