  'Yedekler AES-256-GCM ile parola kullanılarak şifrelenir. Parolanızı unutursanız yedeği açamazsınız. Panoya kopyalanan yedek metnini yine de güvenle saklayın. ÖNEMLİ: Bu işlem cihazdaki canlı kayıtları şifrelemez; bulut yedekleme değildir.': 'Las copias se cifran con AES-256-GCM mediante una contraseña. Si olvidas la contraseña, no podrás abrir la copia. Aun así, guarda en lugar seguro el texto de la copia copiado al portapapeles. IMPORTANTE: Esto no cifra los registros actuales del dispositivo; no es una copia en la nube.',
