  'Yufkaları soslayarak tepsiye kat kat serin, aralara peynir koyun.': 'Coloque la yufka en capas en la bandeja, pincelando con la salsa y poniendo queso entre capas.',
  'Yufkaları soslayıp iç harçla rulo yaparak tepsiye dizin.': 'Pincele la yufka con la salsa, enróllela con el relleno y colóquela en la bandeja.',
  'Yufkaları tepsiye serip her katı sosla ıslatın; iki yufkanın üzerine harcı yayın, kalan yufkaları da sosla ıslatarak kapatın.': 'Extienda la yufka en la bandeja mojando cada capa con salsa; reparta el relleno sobre dos láminas y cubra con las restantes, también mojadas.',
  'Yukarıdaki kutulardan birine dokunarak ilk ölçümünü ekle.': 'Toca una de las casillas de arriba para añadir tu primera medición.',
  'Yulaf, kuru meyve ve keten tohumunu ekleyip kaba bastırın.': 'Añada la avena, la fruta seca y la linaza y presione en el molde.',
  'Yulaf, süt ve elmayı küçük tencereye alın.': 'Ponga la avena, la leche y la manzana en una olla pequeña.',
  'Yulaf, tarçın, tuz ve üzümü ekleyip 5 dakika bekletin.': 'Añada la avena, la canela, la sal y las pasas y deje reposar 5 minutos.',
  'Yulaf, un ve soğuk tereyağını ufalanan kıvama gelene dek karıştırın.': 'Mezcle la avena, la harina y la mantequilla fría hasta que se desmigue.',
  'Yulafı suyla iyice pişirin.': 'Cueza bien la avena con agua.',
  'Yulafın olası çapraz bulaşmasını kontrol edin.': 'Compruebe la avena por posible contaminación cruzada.',
  'Yulafın çapraz bulaşmasını kontrol edin.': 'Compruebe la avena por contaminación cruzada.',
