  'Yumurta, sebze ve ufalanmış peyniri karıştırın.': 'Mezcle los huevos, las verduras y el queso desmenuzado.',
  'Yumurta, süt ve unu çırpıp sebzeleri karıştırın.': 'Bata el huevo, la leche y la harina e incorpore las verduras.',
