  'Yumurtaları çırpıp kabak, havuç, peynir, ince kıyılmış yeşillikler, zeytinyağı, tuz ve karabiberi ekleyin.': 'Bata los huevos y añada el calabacín, la zanahoria, el queso, las hierbas picadas, el aceite, sal y pimienta.',
