  'Yumurtlama döneminde berrak, kaygan akıntı ve hafif kasık ağrısı olabilir.': 'Alrededor de la ovulación puede haber flujo claro y elástico y un leve dolor pélvico.',
  'Yumurtlama ve verimli dönem, ortalama döngü süresine göre yaklaşık hesaplanır. Doğum kontrolü veya gebelik planlaması için güvenilir bir yöntem değildir; tıbbi değerlendirme yerine geçmez.': 'La ovulación y la ventana fértil se estiman a partir de la duración media de tu ciclo. No es un método fiable de anticoncepción ni de planificación del embarazo, y no sustituye una valoración médica.',
  'Yumurtlama çoğunlukla bir sonraki adetten yaklaşık 14 gün önce olur.': 'La ovulación suele ocurrir unos 14 días antes de la siguiente regla.',
