  'Yuvarlak ve köşeli şekilleri birlikte inceleyin.': 'Observen juntos formas redondas y con esquinas.',
  'Yuvarlanma başladığı için alt değiştirme masasında elini bebekten ayırma. Küçük nesneleri, düğme pilleri ve ipleri ulaşamayacağı yerde tut.': 'Ahora que se da la vuelta, mantenga una mano sobre él en el cambiador. Mantenga objetos pequeños, pilas de botón y cordones fuera de su alcance.',
  'Yuvarlanır (çoğunlukla yüzüstüden sırtüstüne); nesneleri ağzına götürür. Adına tepki vermeye başlar, ses tonlarını ayırt eder.': 'Se da la vuelta (normalmente de boca abajo a boca arriba); se lleva objetos a la boca. Empieza a responder a su nombre, distingue los tonos de voz.',
  'Yönetim verilerine erişilemedi. Yönetici yetkinizi, oturumunuzu ve sunucu kurulumunu kontrol edin.': 'No se pudo acceder a los datos de gestión. Revisa el permiso de administrador, la sesión y la configuración del servidor.',
