  'Yüklenen referanslar yalnızca bu ekran açıkken tutulur. 0–24 ay aylık WHO persentilleri bilgi amaçlıdır; tıbbi değerlendirme değildir.': 'Las referencias cargadas solo se conservan mientras esta pantalla está abierta. Los percentiles mensuales de la OMS de 0–24 meses son informativos; no son una valoración médica.',
  'Yüksek ateş, aşırı halsizlik veya uyandırmakta güçlük.': 'Fiebre alta, debilidad extrema o le cuesta despertarse.',
  'Yüksek ateş, nefes darlığı, bayılma, nöbet: 112.': 'Fiebre alta, falta de aire, desmayo, convulsión: llame al número de emergencias local.',
  'Yüksek sarılık değerleri tedavi edilmezse zarar verebilir; bu nedenle kontrol önemlidir.': 'Niveles muy altos de ictericia pueden ser dañinos sin tratamiento, por eso las revisiones son importantes.',
  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'No le deje solo en superficies altas. Mantenga piezas pequeñas, cables, medicamentos y bebidas calientes fuera de su alcance; use una silla de coche adecuada.',
  'Yüksek ısı ve tek kat dizmek karnabaharın haşlanmak yerine kavrulmasını sağlar.': 'El calor alto y una sola capa hacen que la coliflor se tueste en vez de cocerse.',
