  'Yürüme için güvenli alan, basit şekil yerleştirme, birlikte şarkı ve kitap. 1 yaş kontrolüne git.': 'Un espacio seguro para caminar, encajables sencillos, canciones y libros juntos. Acuda a la revisión del año.',
  'Yürüme, ilk kelimeler ve bağımsızlık isteği bu dönemin öne çıkan özellikleridir.': 'Caminar, las primeras palabras y el deseo de independencia marcan esta etapa.',
  'Yürüteç kullanma: düşme ve yaralanma riskini artırır.': 'No use andador: aumenta el riesgo de caídas y lesiones.',
  'Yürüyüş, yüzme, sabit bisiklet ve gebe yogası güvenli seçeneklerdir.': 'Caminar, nadar, la bicicleta estática y el yoga prenatal son opciones seguras.',
  'Yürüyüşle başlayıp yavaş yavaş artır.': 'Empiece caminando y aumente poco a poco.',
  'Yüz ifadeleri başlayabilir; vücudu ince tüylerle (lanugo) kaplanmaya başlar.': 'Pueden empezar las expresiones faciales; el cuerpo se cubre de un vello fino (lanugo).',
  'Yüz ifadelerini keşfet': 'Descubrir las expresiones faciales',
  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'Divida limpieza, hidratación y protección solar en tres pasos cortos. Añada productos nuevos de uno en uno y observe cómo reacciona su piel.',
  'Yüz ve ellerde ani şişlik, nefes darlığı: hemen başvur.': 'Hinchazón repentina de cara y manos, falta de aire: busque ayuda de inmediato.',
