  'İki haftadan uzun süren mutsuzluk, umutsuzluk, uykusuzluk.': 'Tristeza, desesperanza o insomnio durante más de dos semanas.',
  'İki sözcüklü cümleler yaygınlaşır; 50 civarı sözcük olağandır. Taklit ve hayali oyun artar.': 'Las frases de dos palabras son frecuentes; unas 50 palabras es normal. Aumentan la imitación y el juego simbólico.',
  'İki tarafını da içi tamamen pişene dek pişirin.': 'Cocine por ambos lados hasta que estén hechos por dentro.',
  'İki tarafını da içi tamamen pişene kadar çevirerek pişirin.': 'Dé la vuelta y cocine por ambos lados hasta que estén bien hechos.',
  'İki tarafını da içi tamamen pişene kadar çevirin.': 'Dé la vuelta hasta que estén hechas por ambos lados y por dentro.',
  'İki yaş: koşar, top atar, 2–3 sözcüklü cümleler kurar, basit iki aşamalı yönergeleri yapar. Tuvalet eğitimine hazırlık belirtileri görülebilir.': 'Dos años: corre, lanza una pelota, hace frases de 2–3 palabras, sigue órdenes sencillas de dos pasos. Pueden aparecer señales de preparación para dejar el pañal.',
  'İki yüzünü de içi pişene kadar orta ateşte kızartın.': 'Fría por ambos lados a fuego medio hasta que estén hechos.',
  'İki yüzünü de yumurta tamamen pişene kadar pişirin.': 'Cocine por ambos lados hasta que el huevo esté bien cuajado.',
  'İkinci kişi': 'Segundo contacto',
  'İkinci trimester: düzenli kontrolleri ve doktorunun önerdiği taramaları takip et.': 'Segundo trimestre: continúa con los controles regulares y las pruebas que recomiende tu médico.',
  'İkinci üç ay (14–27. hafta)': 'Segundo trimestre (semanas 14–27)',
  'İklim; ilkim': 'Clima; región',
  'İlacın adını, reçeteleyen hekimi, verilen saati ve uygulanan miktarı kayıt notuna ekleyin.': 'Añada a la nota el nombre del medicamento, el médico que lo recetó, la hora y la cantidad.',
  'İlaç & vitamin': 'Medicamentos y vitaminas',
  'İlaç / Vitamin': 'Medicamento / Vitamina',
  'İlaç / vitamin': 'Medicamento / vitamina',
  'İlaç / vitamin ekle': 'Añadir medicamento / vitamina',
  'İlaç günlüğü': 'Diario de medicamentos',
  'İlaç takibi': 'Seguimiento de medicamentos',
  'İlaç ve temizlik ürünlerini kilitli dolapta sakla; zehirlenmede 114. Sıcak içecekleri ve tencere saplarını ulaşamayacağı yerde tut. Su kenarında kol mesafesinde ol.': 'Guarde medicamentos y productos de limpieza bajo llave; ante una intoxicación llame al centro de toxicología. Mantenga las bebidas calientes y los mangos de sartenes fuera de su alcance. Cerca del agua, esté al alcance de la mano.',
  'İlaç ve vitamin': 'Medicamentos y vitaminas',
  'İlaç ve vitamin hatırlatma': 'Recordatorios de medicamentos y vitaminas',
  'İlaç ölçü kaşığı': 'Cucharilla dosificadora',
  'İlaç, temizlik ürünü veya bitki yutulması çocuklarda sık görülen acil durumlardandır.': 'Tragar medicamentos, productos de limpieza o plantas es una urgencia frecuente en niños.',
  'İlaçları ve temizlik ürünlerini kilitli, yüksek dolaplarda orijinal kutusunda sakla.': 'Guarde medicamentos y productos de limpieza en su envase original, bajo llave y en alto.',
  'İlaçları yalnızca yaşa, kiloya ve hekim önerisine uygun şekilde kullanın.': 'Use los medicamentos solo según la edad, el peso y la indicación médica.',
  'İlaçları çocukların erişemeyeceği güvenli bir yerde saklayın.': 'Guarde los medicamentos en un lugar seguro fuera del alcance de los niños.',
  'İlaçları, temizlik ürünlerini ve küçük nesneleri erişimden uzak tutun. Yaşa uygun oto koltuğu kullanın.': 'Mantenga medicamentos, productos de limpieza y objetos pequeños fuera de su alcance. Use una silla de coche adecuada a la edad.',
  'İlerlemeyi mükemmellik üzerinden değerlendirmeyin.': 'No mida su progreso con la perfección.',
  'İletişim': 'Comunicación',
  'İletişim ve önemli notlar': 'Contactos y notas importantes',
  'İletişimde kalmak istediğiniz kişileri belirleyin. Düzenli kısa görüşmeler için uygun zamanlar planlayın.': 'Identifique a las personas con quienes quiere mantener el contacto. Planifique momentos para charlas breves y regulares.',
  'İlgilendiğiniz bir konu seçin. Her gün kısa okuma veya uygulama zamanı ayırın. Öğrendiklerinizi kendi cümlelerinizle not edin.': 'Elija un tema que le interese. Reserve cada día un rato corto para leer o practicar. Anote lo que aprende con sus palabras.',
  'İlgili alanlar': 'Áreas relacionadas',
  'İlgili konular': 'Temas relacionados',
  'İlham': 'Inspiración',
  'İlham, esinti': 'Inspiración, brisa',
  'İlişki sonrası kanama, adetler arası kanama, kötü kokulu akıntı.': 'Sangrado tras las relaciones, sangrado entre reglas, flujo maloliente.',
  'İlişki sırasında ağrı, düzensiz kanama veya ateş eşlik ediyorsa.': 'Si hay dolor en las relaciones, sangrado irregular o fiebre.',
  'İlişkiler': 'Relaciones',
  'İlk 12 hafta': 'Primeras 12 semanas',
  'İlk 12 hafta tamamlandı; takip ve destek devam edebilir.': 'Las primeras 12 semanas han terminado; el seguimiento y el apoyo pueden continuar.',
  'İlk 24 saatte başlayan sarılık ya da avuç içi ve ayak tabanına yayılan sarılık.': 'Ictericia que aparece en las primeras 24 horas o que se extiende a palmas y plantas.',
  'İlk 24 saatte başlayan sarılık.': 'Ictericia que aparece en las primeras 24 horas.',
  'İlk 25 dakika fırın kapağını açmayın.': 'No abra el horno en los primeros 25 minutos.',
  'İlk 6 ay bebeğin ebeveynlerle aynı odada, ama kendi yatağında uyuması önerilir.': 'Durante los primeros 6 meses, el bebé debería dormir en la habitación de los padres pero en su propia cuna.',
  'İlk 6 ay yalnızca anne sütü önerilir; su, şekerli su veya bitki çayı gerekmez. Anne sütü yeterli değilse mama ihtiyacını çocuk doktoruyla değerlendir. Bebek açlık işareti verdikçe besle (günde 8–12 kez).': 'Se recomienda solo leche materna los primeros 6 meses; no hacen falta agua, agua con azúcar ni infusiones. Si la leche materna no basta, hable de la fórmula con su pediatra. Alimente cuando muestre señales de hambre (8–12 veces al día).',
  'İlk 6 ay yalnızca anne sütü, sonrasında ek gıdayla birlikte 2 yaş ve sonrasına kadar emzirme önerilir.': 'Se recomienda lactancia materna exclusiva los primeros 6 meses y después junto con otros alimentos hasta los 2 años o más.',
  'İlk Yardım Çantası': 'Botiquín de primeros auxilios',
  'İlk adım, kelime ve anılar': 'Primeros pasos, palabras y recuerdos',
  'İlk adımlar atılabilir (9–18 ay arası olağandır). 1–3 anlamlı sözcük, el sallama, işaret etme. Kendi başına kaşık kullanmayı dener.': 'Pueden llegar los primeros pasos (entre 9 y 18 meses es normal). 1–3 palabras con significado, decir adiós, señalar. Intenta usar la cuchara solo.',
  'İlk altı ayda bebek başını tutmayı, gülümsemeyi, sesleri takip etmeyi ve yuvarlanmayı öğrenir.': 'En los primeros seis meses el bebé aprende a sostener la cabeza, sonreír, seguir sonidos y darse la vuelta.',
  'İlk ay': 'Primera luna',
  'İlk ay, yeni ay': 'Primera luna, luna nueva',
  'İlk aylarda beslenme': 'Alimentación en los primeros meses',
  'İlk bebeğimi ekle': 'Añadir mi primer bebé',
  'İlk diş hekimi muayenesi ilk dişten sonra ya da 1 yaşında önerilir.': 'Se recomienda una primera visita al dentista tras el primer diente o al año.',
  'İlk dişin çıkış tarihini ve ağız bakım alışkanlıklarını kaydedebilirsiniz.': 'Puede anotar la fecha del primer diente y los hábitos de cuidado bucal.',
  'İlk dişler çoğunlukla 6. ay civarında çıkar; bu süreçte huzursuzluk ve salya artışı olabilir.': 'Los primeros dientes suelen salir hacia los 6 meses; puede haber irritabilidad y más babeo.',
  'İlk dişten itibaren günde iki kez, pirinç tanesi kadar florürlü diş macunuyla fırçala.': 'Desde el primer diente, cepille dos veces al día con una cantidad de pasta con flúor del tamaño de un grano de arroz.',
  'İlk doğan': 'Primogénito',
  'İlk doğan can': 'Alma primogénita',
  'İlk doğumlarda doğum eylemi genellikle daha uzun sürer.': 'El parto suele durar más con el primer hijo.',
  'İlk er': 'Primer hombre',
  'İlk gebelik, ikiz gebelik, kronik hipertansiyon ve böbrek hastalığı riski artırır.': 'Un primer embarazo, gemelos, la hipertensión crónica y las enfermedades renales aumentan el riesgo.',
  'İlk gebelikte hareketler genellikle 18–22. haftada, sonraki gebeliklerde daha erken hissedilir.': 'En el primer embarazo los movimientos suelen notarse hacia las semanas 18–22; en los siguientes, antes.',
  'İlk günler: Taburculuk önerilerini, kanama miktarını ve ağrı kontrolünü takip edin. Evde destek planı oluşturun.': 'Primeros días: sigue las indicaciones del alta, la cantidad de sangrado y el control del dolor. Haz un plan de apoyo en casa.',
  'İlk günlerde erken hareket etmek pıhtı riskini azaltır.': 'Moverse pronto los primeros días reduce el riesgo de trombos.',
  'İlk günlerde gelen kolostrum az ama yeterlidir; süt genellikle 2–5. günde artar.': 'El calostro de los primeros días es poco pero suficiente; la leche suele aumentar entre el día 2 y 5.',
  'İlk günlerde hafif hassasiyet olağandır; süren ağrı olağan değildir.': 'Una leve sensibilidad los primeros días es normal; el dolor persistente no.',
  'İlk günlerde kısa süreli kalışla başla.': 'Empiece con estancias cortas los primeros días.',
  'İlk günlerdeki koyu yeşil-siyah kaka (mekonyum) birkaç gün içinde sarıya döner.': 'Las heces verde-negruzcas de los primeros días (meconio) se vuelven amarillas en pocos días.',
  'İlk haftalar beslenme, uyku ve alışma dönemidir; bebeğin kilo vermesi ve sık uyanması çoğu zaman olağandır.': 'Las primeras semanas son un tiempo de tomas, sueño y conocerse; la pérdida de peso y los despertares frecuentes suelen ser normales.',
  'İlk haftalar için esnek çalışma seçeneklerini işvereninle konuş.': 'Hable con su empresa sobre opciones flexibles para las primeras semanas.',
  'İlk haftalarda ağlama ve uyku-iştah değişiklikleri olabilir.': 'En las primeras semanas puede haber llanto y cambios de sueño y apetito.',
  'İlk hareketler çoğunlukla 18–22. haftalarda hissedilir.': 'Los primeros movimientos suelen notarse entre las semanas 18 y 22.',
  'İlk hareketleri "kelebek kanadı" gibi hissedebilirsin (özellikle önceki gebeliklerde).': 'Puede notar los primeros movimientos como «alas de mariposa» (sobre todo en embarazos posteriores).',
  'İlk insan; toprak': 'El primer ser humano; tierra',
  'İlk kadın, Âdem’in eşi': 'La primera mujer, esposa de Adán',
  'İlk muayenede gebeliğin yeri ve haftası ultrasonla doğrulanır.': 'En la primera visita se confirman por ecografía la ubicación y las semanas de embarazo.',
  'İlk muayenende kronik hastalıklarını ve ilaçlarını gözden geçir.': 'En la primera visita, revise sus enfermedades crónicas y medicamentos.',
  'İlk saatte bebeğin memeyi aramasına fırsat ver.': 'En la primera hora, dé a su bebé la oportunidad de encontrar el pecho.',
  'İlk trimester: kontroller, beslenme ve kullandığın ilaçlar hakkında doktorunla görüş.': 'Primer trimestre: habla con tu médico sobre los controles, la alimentación y los medicamentos que tomas.',
  'İlk ultrasonla gebelik haftası doğrulanır; tahmini doğum tarihini uygulamaya gir.': 'La primera ecografía confirma la semana de embarazo; introduzca su fecha probable de parto en la app.',
  'İlk yaklaşık 6 ay temel besin anne sütü veya uygun bebek formülüdür. Ek gıdaya başlama zamanını sağlık uzmanıyla değerlendirin.': 'Durante aproximadamente los primeros 6 meses el alimento principal es la leche materna o una fórmula adecuada. Hable con un profesional sobre cuándo empezar los sólidos.',
  'İlk yardım eğitimi ve acil yardım erişimi önemlidir.': 'La formación en primeros auxilios y el acceso a ayuda urgente son importantes.',
